import {bindAtmosphere} from './atmosphere.js';
import {createWeekFlow} from './weekflow.js';
import {createCommunityExperience} from './community-ui.js';
import {ingredients,recipes,consolidate,consolidateWeek,lunchForDay,servingsForDay,courseServings,supperPeople,weekEntries,activeDays,dayCount,quantityLabel,physicalQuantity,normalizeProfile,allergenLabels,equipmentLabels,eventLabels,ingredientCategories,eligibleRecipes,planCost,generatePlan,lunchVariant} from './domain.js';
import {storeDirectory,normalizeStore,validPostal,normalizeOffer,offerStatus,purchaseEstimate,localDate,validDate,occasionTimeline,clockLabel,pantryBalance} from './commerce.js';
import {desireResults,discoveryBatch,createExperienceGateway,approvedRecipeIds} from './discovery.js';
const KEY='mijote-luxe-v2';
const DEFAULT={profile:normalizeProfile({}),pantry:{},pantryPriority:[],locked:{},prepChecks:{},extraItems:[],courses:{},ids:[],favorites:[],checked:{},rotation:0,onboarded:false};
let state=structuredClone(DEFAULT);
const clamp=(v,min,max,fallback=min)=>Number.isFinite(Number(v))?Math.min(max,Math.max(min,Number(v))):fallback;
try{const a=JSON.parse(localStorage.getItem(KEY));if(a){state={...state,...a};state.profile=normalizeProfile(a.profile||{});for(const [k,min,max] of [['people',1,12],['lunch',0,12],['budget',1,3000]])state.profile[k]=clamp(state.profile[k],min,max);state.profile.people=Math.round(state.profile.people);state.profile.lunch=Math.round(state.profile.lunch);state.profile.maxTime=[25,40,60].includes(state.profile.maxTime)?state.profile.maxTime:40;state.profile.veg=!!state.profile.veg;state.profile.goal=['discover','budget','waste','quick'].includes(state.profile.goal)?state.profile.goal:'discover';state.profile.excluded=(Array.isArray(state.profile.excluded)?state.profile.excluded:[]).filter(id=>ingredients[id]);state.ids=Array.isArray(a.ids)&&[5,7].includes(a.ids.length)&&a.ids.every(id=>id===null||recipes.some(r=>r.id===id&&r.course==='main'))?a.ids:[];state.favorites=(Array.isArray(a.favorites)?a.favorites:[]).filter(id=>recipes.some(r=>r.id===id));state.pantry=Object.fromEntries(Object.entries(a.pantry||{}).filter(([id])=>ingredients[id]).map(([id,n])=>[id,clamp(n,0,100000)]));state.checked=a.checked&&typeof a.checked==='object'?a.checked:{};state.rotation=Math.round(clamp(a.rotation,0,10000));}}catch{}
state.profile=normalizeProfile(state.profile);
state.courses=Object.fromEntries(Object.entries(state.courses||{}).filter(([index])=>Number(index)>=0&&Number(index)<=6).map(([index,items])=>[index,Object.fromEntries(['starter','dessert'].filter(kind=>recipes.some(r=>r.id===items?.[kind]&&r.course===kind)).map(kind=>[kind,items[kind]]))]));
if(state.ids.length)state.ids=Array.from({length:dayCount(state.profile)},(_,i)=>activeDays(state.profile).includes(i)?state.ids[i]||null:null);
state.pantryPriority=(Array.isArray(state.pantryPriority)?state.pantryPriority:[]).filter(id=>Object.hasOwn(ingredients,id));
state.locked=state.locked&&typeof state.locked==='object'?state.locked:{};
state.prepChecks=state.prepChecks&&typeof state.prepChecks==='object'?state.prepChecks:{};
state.extraItems=(Array.isArray(state.extraItems)?state.extraItems:[]).filter(r=>r&&typeof r.name==='string'&&typeof r.id==='string').slice(0,100).map(r=>({id:r.id.replace(/[^a-zA-Z0-9-]/g,'').slice(0,40),name:r.name.slice(0,60),quantity:String(r.quantity||'').slice(0,30),estimatedPrice:r.estimatedPrice===null||r.estimatedPrice===''?null:clamp(r.estimatedPrice,0,10000)}));
state.baseProfile=normalizeProfile({...state.baseProfile||state.profile,events:{}});
state.store=normalizeStore(state.store);
state.shoppingDate=validDate(state.shoppingDate)&&state.shoppingDate>=localDate()?state.shoppingDate:localDate();
state.offers=(Array.isArray(state.offers)?state.offers:[]).map(o=>normalizeOffer(o,Object.keys(ingredients))).filter(Boolean).slice(0,200);
state.history=(Array.isArray(state.history)?state.history:[]).filter(h=>h&&Array.isArray(h.ids)&&h.profile).slice(0,20);
state.notes=Object.fromEntries(recipes.filter(r=>state.notes?.[r.id]).map(r=>[r.id,{text:String(state.notes[r.id].text||'').slice(0,1000),rating:clamp(state.notes[r.id].rating,0,5)}]));
state.expiry=state.expiry&&typeof state.expiry==='object'?state.expiry:{};
state.timer=state.timer&&Number.isFinite(state.timer.endsAt)?state.timer:null;
let recipeScale=null,pendingPartial=null;
let page='home',draft=null,step=0,selectedDay=0,filter='all',search='',chatAnswer='',recipeDay=0;
const detailsOpen=new Set();
const experienceGateway=createExperienceGateway(globalThis.MIJOTE_CONFIG||{});
let desireRound=0,desireSeen=[],lastDiscoveryIds=[],desireBusy=false,desireRequest=0,desireNotice='',providerRecipeIds=null;
let automaticOffers=[],offerFeed={status:'unavailable',key:'',provider:'',verifiedAt:null};

const days=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];
const eventImages={romantic:'hero',italian:'pizza',mexican:'tacos',asian:'curry',brunch:'pancakes',bbq:'bbq',family:'roast-chicken'};
let occasionDraft=null,courseFilter='all',themeFilter='',visibleRecipes=12;
const money=n=>new Intl.NumberFormat('fr-CA',{style:'currency',currency:'CAD'}).format(n);
const qty=n=>new Intl.NumberFormat('fr-CA',{maximumFractionDigits:0}).format(n);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 3M18 18A8 8 0 0 1 5 15"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bag:'<path d="M5 7h14l1 14H4L5 7Zm3 0V5a4 4 0 0 1 8 0v2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',check:'<path d="m5 12 4 4L19 6"/>'})[name]||''}</svg>`;
const photo=(r,cls='',loading='lazy')=>r.userPhoto?`<img class="${cls}" src="${r.userPhoto}" alt="${esc(r.name)}" loading="${loading}">`:!r.photoVerified?'<div class="photo-pending">Photo de ce plat en préparation.</div>':`<img class="${cls}" src="assets/${r.image}.jpg" alt="${esc(r.photoAlt||r.name)}" loading="${loading}" style="object-position:${r.id==='tofu'?'80% 28%':r.id==='boeuf'?'58% 70%':'center'}">`;
const dish=id=>recipes.find(r=>r.id===id);
const portions=(index=selectedDay)=>servingsForDay(state.profile,index);
const shopping=()=>consolidateWeek(state.ids,state.profile,state.pantry,state.courses);
const cost=()=>planCost(state.ids,state.profile,state.pantry,state.courses);
const extraCost=()=>state.extraItems.reduce((n,r)=>n+(r.estimatedPrice||0),0);
const perPortion=r=>Object.entries(r.items).reduce((n,[id,q])=>n+q*ingredients[id][2],0);
function persistLocal(){try{localStorage.setItem(communityUI.localKey(),JSON.stringify(state));}catch{toast('Votre navigateur ne permet pas la sauvegarde. Les changements restent disponibles pendant cette visite.');}}
function recipePrice(r){return Object.keys(r.items).some(id=>ingredients[id]?.priceKnown===false)?'Prix partiel '+money(perPortion(r)):money(perPortion(r));}
function save(){persistLocal();communityUI.queueSave();}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';clearTimeout(window.mijoteToast);window.mijoteToast=setTimeout(()=>el.style.display='none',Math.max(4200,Math.min(12000,text.length*50)));}
function go(next){document.querySelector('#modal').close();page=next;history.replaceState(null,'','#'+next);render();window.scrollTo(0,0);}
function startQuiz(){if(!restoreDraft()){draft={profile:structuredClone(state.profile),pantry:structuredClone(state.pantry),priority:state.pantryPriority.slice()};step=0;}go('quiz');}
function restoreDraft(){try{const stored=JSON.parse(localStorage.getItem(communityUI.localKey()+'-draft'));if(!stored?.draft)return false;draft={profile:normalizeProfile(stored.draft.profile),pantry:Object.fromEntries(Object.entries(stored.draft.pantry||{}).filter(([id])=>Object.hasOwn(ingredients,id)).map(([id,n])=>[id,clamp(n,0,100000)])),priority:(Array.isArray(stored.draft.priority)?stored.draft.priority:[]).filter(id=>Object.hasOwn(ingredients,id))};step=Math.round(clamp(stored.step,0,4));return true;}catch{return false;}}
function planOptions(){return {locked:state.ids.map((id,i)=>state.locked[i]?id:null),priority:state.pantryPriority,recent:state.history.slice(0,3).flatMap(h=>h.ids||[]),offerPrices:currentOfferPrices()};}
function dietLabel(p){return ({varied:'Varié',vegetarian:'Végétarien',vegan:'Végétalien',pescatarian:'Poisson & végétal'})[p.diet]||'Varié';}
function sizeLabel(p){return ({small:'Petites portions · −25 % d’ingrédients',standard:'Portions standard',generous:'Portions généreuses · +25 % d’ingrédients'})[p.portionSize];}
function fold(id,title,subtitle,body){return `<details class="detail-fold" data-fold="${id}" ${detailsOpen.has(id)?'open':''}><summary><span>${title}<small>${subtitle}</small></span><span class="fold-symbol" aria-hidden="true">+</span></summary><div class="fold-body">${body}</div></details>`;}
function render(){
 if(page==='market'){page='list';history.replaceState(null,'','#list');}
 const active=document.activeElement;
 const focusKeys=['data-choice','data-setting','data-value','data-counter','data-delta','data-exclude','data-allergen','data-equipment','data-lunch-day','data-favorite','data-day','data-filter','data-lock','data-priority'];
 const focusSelector=active?.tagName==='BUTTON'?focusKeys.filter(k=>active.hasAttribute(k)).map(k=>'['+k+'="'+active.getAttribute(k).replace(/["\\]/g,'\\$&')+'"]' ).join(''):'';
 if(page==='quiz'&&draft){try{localStorage.setItem(communityUI.localKey()+'-draft',JSON.stringify({draft,step}));}catch{}}
 document.querySelector('#header').innerHTML=`<a class="brand" href="#home" aria-label="Sauge, accueil"><svg class="brand-sprig" viewBox="0 0 30 38" aria-hidden="true"><path d="M7 34C10 20 15 11 24 3M12 22C3 22 2 15 3 10c7 0 12 3 9 12ZM17 13c-1-8 3-11 9-12 2 7-1 12-9 12ZM11 26c6-6 13-5 16-2-4 7-10 8-16 2Z"/></svg>sauge<span style="color:var(--gold)">.</span></a><nav class="nav" aria-label="Navigation principale">${[['explore','Découvrir'],['menu','Ma semaine'],['list','Épicerie']].map(([p,n])=>`<a href="#${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="nav-actions"><button class="account-link" data-account>Mon compte</button></div>`;
 document.querySelector('#main').innerHTML=communityUI.demoBanner()+(({ home,quiz,explore:()=>explore(false),favorites:()=>explore(true),menu,list,pantry,plans,market,journal,personal:communityUI.personalPage,admin:communityUI.adminPage})[page]?.()||home());
 document.querySelector('#footer').innerHTML=`<div class="forest-footer-brand"><a class="brand" href="#home">sauge<span>.</span></a><p>Les bonnes idées finissent<br>toujours autour d’une table.</p><small>Pensé au Québec · FR · $ CA</small></div><div class="forest-footer-links"><span>À TABLE</span><button data-go="explore">Découvrir les plats</button><button data-go="menu">Ma semaine</button><button data-go="list">Mon épicerie</button></div><div class="forest-footer-links"><span>À VOTRE GOÛT</span><button data-account>Mon compte</button><button data-go="plans">Sauge Plus</button><button data-info>À propos de cet aperçu</button></div><div class="forest-footer-note"><span class="handwritten">Bien manger.<br>Tout simplement.</span><p>Du quotidien aux soirs<br>qu’on prend le temps de savourer.</p></div>`;
 bind();communityUI.bind(document);bindAtmosphere(document);bindExperience();bindDiscovery();bindWeekTools();updateTimer();syncAutomaticOffers();
 if(focusSelector)document.querySelector('#main '+focusSelector)?.focus({preventScroll:true});
}
function card(r){return `<article class="dish"><div class="dish-visual"><button class="photo-open" data-recipe="${r.id}" aria-label="Voir la recette ${esc(r.name)}">${photo(r)}</button><button class="save ${state.favorites.includes(r.id)?'on':''}" data-favorite="${r.id}" aria-label="${state.favorites.includes(r.id)?'Retirer des':'Ajouter aux'} favoris : ${esc(r.name)}" aria-pressed="${state.favorites.includes(r.id)}">${icon('heart')}</button><span class="photo-tag">${r.course==='starter'?'L’entrée':r.course==='dessert'?'Le dessert':r.tag}</span>${liveOffers().some(o=>o.isSale&&o.ingredient in r.items)?'<span class="ingredient-deal">Un ingrédient en rabais</span>':''}</div><div class="dish-info"><h3><button data-recipe="${r.id}" style="padding:0;text-align:left">${r.name}</button></h3><p class="fine">${r.ratingCount?Number(r.ratingAverage).toFixed(1).replace(".",",")+" / 5 · "+r.ratingCount+" avis":"Pas encore d’avis"}${r.accountRecipe?" · "+esc(r.creator):""}</p><div class="dish-meta"><span>${r.time} min</span><span>${recipePrice(r)} / portion*</span><button data-recipe="${r.id}" aria-label="Ouvrir ${esc(r.name)}">${icon('arrow')}</button></div><button class="dish-add" data-add="${r.id}">À mon menu +</button></div></article>`;}
function home(){return `<div class="forest-home"><section class="forest-hero"><img class="forest-hero-scene" src="assets/forest-table-v1.png" alt="" aria-hidden="true" fetchpriority="high"><div class="forest-hero-copy"><span class="forest-kicker">Sauge · Le goût des bonnes semaines</span><h1>Du plaisir<br>dans <em>l’assiette.</em><br><span>Du temps pour vous.</span></h1><p>Des soupers qu’on a hâte de cuisiner.<br>Une semaine à votre goût, une épicerie toute prête.<br>Et le plaisir de se retrouver à table.</p><div class="forest-hero-actions"><button class="primary" data-go="explore">Qu’est-ce qu’on mange? ${icon('arrow')}</button><button class="forest-subtle" data-generate-week>Préparer ma semaine →</button></div><div class="forest-hero-promises"><span>${icon('check')} Vos goûts, vos portions</span><span>${icon('check')} Votre budget en tête</span></div></div><div class="forest-hero-seal"><span>Fait pour</span><strong>les bonnes<br>tablées.</strong><small>Pensé au Québec</small></div></section><section class="forest-intro"><span class="handwritten">La semaine a meilleur goût.</span><h2>Bien manger commence<br>par <em>l’envie.</em></h2><p>Les bons ingrédients. Une idée qui vous tente.<br>On s’occupe de rendre le reste plus simple.</p><div class="forest-leaf-divider" aria-hidden="true">❧</div></section><section class="forest-story wrap"><div class="forest-story-art"><img src="assets/sauge-layers-cutout-v2.png" alt="Composition culinaire décorative : légumes et pois chiches mis en scène au-dessus d’une assiette" loading="lazy"></div><div class="forest-story-copy"><span class="handwritten">À votre façon</span><h2>Une belle semaine.<br><em>Sans se compliquer<br>la vie.</em></h2><div class="forest-steps"><article><span>01</span><div><h3>Vous nous dites ce qui vous tente.</h3><p>Un lundi pressé, un petit budget, une envie d’Italie… Chaque souper trouve sa place.</p></div></article><article><span>02</span><div><h3>Vous choisissez vos plats.</h3><p>Quelques bonnes idées par jour. Des portions pour vous, et des lunchs si vous en voulez.</p></div></article><article><span>03</span><div><h3>Votre épicerie suit, tout simplement.</h3><p>Les ingrédients sont regroupés et ce que vous avez déjà est déduit de la liste.</p></div></article></div><button class="secondary" data-generate-week>On prépare ma semaine ${icon('arrow')}</button></div></section><section class="forest-collection wrap"><div class="section-head"><div><span class="handwritten">Ça donne envie, non?</span><h2>Quelques idées<br>pour <em>ce soir.</em></h2></div><button class="text-link" data-go="explore">Toute la collection ${icon('arrow')}</button></div><div class="recipe-grid">${['saumon','pates','risotto-champignons'].map(id=>card(dish(id))).join('')}</div><p class="photo-disclaimer">Photographies des plats de la collection. Coûts indicatifs des ingrédients, avant déduction de votre inventaire.</p></section><section class="forest-occasions"><div class="forest-occasion-heading"><span class="handwritten">Il n’y a pas que le lundi.</span><h2>Une envie de<br><em>faire un peu plus?</em></h2><p>Un souper à deux, une grande tablée ou un brunch qui s’étire.<br>Gardez le plaisir de recevoir.</p></div><div class="forest-occasion-grid">${[['romantic','Un soir à deux','Une belle assiette. Le reste peut attendre.'],['italian','Comme en Italie','On met la table, on prend son temps.'],['brunch','Un dimanche gourmand','Du café chaud et rien qui presse.']].map(([id,label,text])=>`<button data-event-preset="${id}" class="forest-occasion-card"><img src="assets/${eventImages[id]}.jpg" alt="" loading="lazy"><span><small>${label}</small><strong>${text}</strong><em>Organiser cette occasion · ✦ Plus ↗</em></span></button>`).join('')}</div></section>${trustSection()}${plusTeaser()}<section class="forest-last-call wrap"><div><span class="handwritten">On passe à table?</span><h2>Votre prochain bon souper<br><em>commence ici.</em></h2></div><button class="primary" data-go="explore">Trouver mon prochain plat ${icon('arrow')}</button></section></div>`;}

const goals=[['discover','Retrouver l’envie de cuisiner','Des plats variés pour sortir de la routine.'],['budget','Mieux manger, mieux dépenser','Des choix économiques et un budget visible.'],['quick','Passer moins de temps en cuisine','Des soupers de 25 minutes ou moins.'],['waste','Utiliser ce que j’ai déjà','Faire une place au contenu du garde-manger.']];
function choice(key,value,title,sub,index){const selected=String(draft.profile[key])===String(value);return `<button class="choice ${selected?'selected':''}" data-choice="${key}" data-value="${value}" aria-pressed="${selected}"><span class="choice-number">${String(index+1).padStart(2,'0')}</span><span><strong>${title}</strong><small>${sub}</small></span><span class="tick">${selected?'✓':''}</span></button>`;}
function counter(key,title,desc,min){return `<div class="counter-row"><div><strong>${title}</strong><small>${desc}</small></div><div class="counter"><button data-counter="${key}" data-delta="-1" aria-label="Diminuer ${title}" ${draft.profile[key]<=min?'disabled':''}>−</button><b aria-live="polite">${draft.profile[key]}</b><button data-counter="${key}" data-delta="1" aria-label="Augmenter ${title}" ${draft.profile[key]>=12?'disabled':''}>+</button></div></div>`;}
function quiz(){
 if(!draft)draft={profile:structuredClone(state.profile),pantry:structuredClone(state.pantry),priority:state.pantryPriority.slice()};
 const p=draft.profile;
 const titles=['Qu’est-ce qui vous<br><em>ferait du bien?</em>','On met la table<br><em>pour combien?</em>','Et dans votre<br><em>assiette?</em>','À votre rythme.<br><em>À votre budget.</em>','Avant de faire<br><em>l’épicerie…</em>'];
 const intros=['Le plus important d’abord. Les détails sont là si vous en avez besoin.','Les soupers et les lunchs se préparent ensemble. Vous gardez la main sur les quantités.','Vos goûts comptent. Vos contraintes aussi.','Un menu qui trouve sa place dans votre vraie vie.','Utilisons ce qui est déjà à la maison. Vous pourrez compléter l’inventaire plus tard.'];
 let body='';
 if(step===0)body=`<div class="choices">${goals.map(([v,t,s],i)=>choice('goal',v,t,s,i)).join('')}</div><div class="quiet-note">Cinq étapes courtes · détails facultatifs · progression enregistrée sur cet appareil.</div>`;
 if(step===1){
  const lunchSchedule=p.lunch?days.slice(0,dayCount(p)).map((day,i)=>`<button class="chip ${p.lunchDays.includes(i)?'active':''}" data-lunch-day="${i}" aria-pressed="${p.lunchDays.includes(i)}">${day}</button>`).join(''):'<p class="fine">Ajoutez des portions lunch pour choisir les soirs à cuisiner en double.</p>';
  body=counter('people','Personnes au souper','Le nombre de portions servies le soir.',1)+counter('lunch','Portions lunch à réserver','En plus du souper, pour les soirs de votre choix.',0)+`<div class="review"><strong>${p.people} au souper</strong>${p.lunch?` + ${p.lunch} lunch${p.lunch>1?'s':''} sur ${p.lunchDays.length} soir${p.lunchDays.length>1?'s':''}`:' · sans portion lunch'}<br><span class="fine">${sizeLabel(p)}</span></div>`;
  body+=`<span class="field-label">Le lunch du lendemain</span><div class="filters">${[['same','Le même plat, prêt à réchauffer'],['transform','Transformer quand une variante est disponible']].map(([v,label])=>`<button class="chip ${p.lunchStyle===v?'active':''}" data-setting="lunchStyle" data-value="${v}" ${v==='transform'?'data-plus="lunch-transform"':''} aria-disabled="${v==='transform'&&!hasPlus()}">${label}${v==='transform'?'<span class="plus-badge">✦ Plus</span>':''}</button>`).join('')}</div><p class="fine">Les variantes calculées ajoutent leurs ingrédients à la liste. Si aucune variante compatible n’existe, le même plat est réservé.</p>`;
  body+=fold('household-detail','Affiner les portions et les lunchs',`${p.lunchMode==='cold'?'Lunchs à manger froids':'Lunchs à réchauffer'} · options facultatives`,`<span class="field-label">Votre appétit habituel</span><div class="filters">${[['small','Petites'],['standard','Standard'],['generous','Généreuses']].map(([v,label])=>`<button class="chip ${p.portionSize===v?'active':''}" data-setting="portionSize" data-value="${v}" aria-pressed="${p.portionSize===v}">${label}</button>`).join('')}</div><p class="fine">Petites : 25 % d’ingrédients en moins. Généreuses : 25 % de plus. Un réglage d’appétit, identique pour toutes les portions du foyer.</p><span class="field-label">Quels soupers doivent aussi donner des lunchs?</span><div class="filters">${lunchSchedule}</div><p class="fine">Le souper du lundi prépare le lunch du mardi, et ainsi de suite. Désélectionnez un soir si aucun lunch n’est nécessaire.</p><span class="field-label">Au moment du lunch</span><div class="filters">${[['warm','Je peux réchauffer'],['cold','Je le mange froid']].map(([v,label])=>`<button class="chip ${p.lunchMode===v?'active':''}" data-setting="lunchMode" data-value="${v}" aria-pressed="${p.lunchMode===v}">${label}</button>`).join('')}</div><p class="fine">Le choix « froid » retient des plats adaptés à ce mode de service. Une conservation au froid reste nécessaire.</p>`);
 }
 body+=step===1?fold('week-schedule','Choisir mes journées',activeDays(p).length+' journées prévues · fin de semaine facultative',calendarControls(p,true)):'';
 if(step===2){
  body=`<div class="diet-choice-grid">${[['varied','Un peu de tout','Viande, poisson, végétal.'],['vegetarian','Végétarien','Sans viande ni poisson.'],['pescatarian','Poisson & végétal','Sans viande, avec poisson.'],['vegan','Végétalien','Sans ingrédient d’origine animale.']].map(([v,t,s],i)=>choice('diet',v,t,s,i)).join('')}</div><p class="fine mt">Votre choix : <strong>${dietLabel(p)}</strong>.</p>`;
  body+=fold('food-constraints','Allergies et ingrédients à éviter',`${p.allergens.length} contrainte${p.allergens.length>1?'s':''} déclarée${p.allergens.length>1?'s':''} · ${p.excluded.length} ingrédient${p.excluded.length>1?'s':''} exclu${p.excluded.length>1?'s':''}`,`<span class="field-label">Allergies et intolérances à prendre en compte</span><div class="filters">${Object.entries(allergenLabels).map(([id,name])=>`<button class="chip ${p.allergens.includes(id)?'active':''}" data-allergen="${id}" aria-pressed="${p.allergens.includes(id)}">${name}</button>`).join('')}</div><p class="fine">Les recettes contenant ces allergènes dans leurs ingrédients déclarés seront exclues. Vérifiez les étiquettes des produits et les traces possibles : le filtre ne garantit pas l’absence de contamination. Ces choix restent sur cet appareil.</p><span class="field-label">Des ingrédients que vous n’aimez pas?</span><input id="exclude-search" class="exclude-search" placeholder="Chercher un ingrédient…" aria-label="Filtrer les ingrédients à exclure"><div class="filters exclude-cloud">${Object.entries(ingredients).map(([id,r])=>`<button class="chip ${p.excluded.includes(id)?'active':''}" data-exclude="${id}" aria-pressed="${p.excluded.includes(id)}">${r[0]}</button>`).join('')}</div><p class="fine">Plus les exclusions sont nombreuses, plus le choix de recettes est limité. Nous vous le dirons si aucun menu ne convient.</p>`);
 }
 if(step===3){
  body=`<span class="field-label">Temps total par souper</span><div class="choices">${choice('maxTime',25,'25 minutes maximum','Préparation et cuisson, en parallèle lorsque possible.',0)}${choice('maxTime',40,'Jusqu’à 40 minutes','Un peu plus de temps pour se faire plaisir.',1)}${choice('maxTime',60,'Jusqu’à 60 minutes','Pour les repas qu’on prend plaisir à préparer.',2)}</div><label class="field-label" for="quiz-budget">Budget pour les ${activeDays(p).length} journées, lunchs et occasions inclus</label><div class="budget-input"><input id="quiz-budget" type="number" min="1" max="3000" value="${p.budget}" inputmode="numeric"><span>$ CA</span></div><p class="fine mt">Les quantités déjà en stock sont déduites. Les formats achetés et les prix en magasin peuvent faire varier le total en caisse.</p>`;
  body+=storeFields(state.store,'quiz');
  body+=fold('kitchen-detail','Votre aisance et votre équipement',`${p.level==='beginner'?'Cuisine facile':'À l’aise en cuisine'} · ${p.equipment.length} équipement${p.equipment.length>1?'s':''}`,`<span class="field-label">Vous préférez…</span><div class="filters">${[['beginner','Des gestes simples'],['comfortable','Je suis à l’aise']].map(([v,label])=>`<button class="chip ${p.level===v?'active':''}" data-setting="level" data-value="${v}" aria-pressed="${p.level===v}">${label}</button>`).join('')}</div><span class="field-label">Les équipements disponibles pour le souper</span><div class="filters">${Object.entries(equipmentLabels).map(([id,name])=>`<button class="chip ${p.equipment.includes(id)?'active':''}" data-equipment="${id}" aria-pressed="${p.equipment.includes(id)}">${name} · ${recipes.filter(r=>r.photoVerified&&r.equipment.includes(id)).length}</button>`).join('')}</div><p class="fine">Le nombre indique les recettes illustrées utilisant cet équipement. Les recettes demandant un appareil non sélectionné sont écartées. Les ustensiles de base et un thermomètre de cuisson sont à prévoir.</p><label class="long-cook"><input type="checkbox" id="allow-long-cook" ${p.allowLongCook?'checked':''}> J’accepte une cuisson longue sans surveillance continue (mijoteuse)</label><p class="fine">Ces recettes dépassent la durée choisie plus haut; leur temps total reste affiché. Respectez toujours les consignes de votre appareil.</p>`);
 }
 if(step===4){
  body=`<div class="stock-grid">${['rice','pasta','carrot','chickpea'].map(id=>`<div class="stock-field"><label for="quiz-stock-${id}">${ingredients[id][0]}</label><input type="number" id="quiz-stock-${id}" data-quiz-stock="${id}" value="${draft.pantry[id]||0}" min="0" max="100000"><small>g</small></div>`).join('')}</div>`;
  body+=fold('stock-detail','Compléter l’inventaire','Facultatif · quantités disponibles avant de commencer la semaine',`<div class="stock-grid">${Object.entries(ingredients).filter(([id])=>!['rice','pasta','carrot','chickpea'].includes(id)).map(([id,r])=>`<div class="stock-field"><label for="quiz-stock-${id}">${r[0]}</label><input type="number" id="quiz-stock-${id}" data-quiz-stock="${id}" value="${draft.pantry[id]||0}" min="0" max="100000"><small>${r[1]}</small></div>`).join('')}</div><p class="fine mt">Indiquez le poids disponible pour cuisiner : riz et pâtes secs, légumineuses déjà cuites et égouttées.</p>`);
  body+=`<div class="review">${activeDays(p).length} journées · ${p.people} personnes · ${p.lunch} lunchs sur les soirs choisis<br>${dietLabel(p)} · ${p.maxTime} min maximum · ${sizeLabel(p)}<br>Budget visé : <strong>${money(p.budget)}</strong>${p.allergens.length?`<br>Filtres allergènes : ${p.allergens.map(id=>allergenLabels[id]).join(', ')}`:''}${!p.equipment.length?'<br><span class="warning">Aucun équipement sélectionné : il faudra en choisir un pour ce catalogue.</span>':''}</div><div id="quiz-error" role="alert"></div>`;
 }
 return `<section class="quiz-shell"><div class="quiz-content"><div class="quiz-top"><button class="quiz-back" id="quiz-back">← ${step?'Retour':'Accueil'}</button><span>VOTRE MENU · 0${step+1} / 05</span></div><div class="quiz-progress">${Array.from({length:5},(_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><span class="quiz-importance ${[0,4].includes(step)?'optional':'essential'}">${[0,4].includes(step)?'Facultatif · à compléter plus tard':'L’essentiel pour votre menu'}</span><h1>${titles[step]}</h1><p>${intros[step]}</p>${body}<button class="primary quiz-next" id="quiz-next">${step===4?'Découvrir mon menu':'Continuer'} ${icon('arrow')}</button>${[0,4].includes(step)?'<button class="text-link quiz-later" id="quiz-later">Compléter plus tard →</button>':''}<button class="text-link quiz-save-exit" id="quiz-save-exit">Enregistrer et reprendre plus tard</button>${step?'<button class="quiz-restart" id="quiz-restart">Reprendre les réglages de mon dernier menu</button>':''}</div><div class="quiz-photo"><img src="assets/${['salmon','roast-chicken','tofu','pasta','chickpeas'][step]}.jpg" alt="Inspiration culinaire pour votre menu"><div class="quiz-caption"><div class="eyebrow">Sauge, à votre goût</div><h2>Une belle semaine<br>commence <em>à table.</em></h2><p class="fine">Les soupers d’aujourd’hui. Les lunchs de demain.</p></div></div></section>`;
}

function title(eyebrow,heading,sub,actions=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p>${sub}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function emptyPlan(){return `<div class="wrap new-week-page">${title('Vos habitudes sont déjà prêtes',state.weekUndo?'Une nouvelle semaine.<br><em>À votre goût.</em>':'Votre semaine.<br><em>On s’en occupe.</em>','Générez un menu avec vos préférences enregistrées, ou commencez par un plat qui vous fait envie.')}<div class="week-start-actions"><button class="primary" data-generate-week>Préparer ma nouvelle semaine ${icon('arrow')}</button><button class="secondary" data-go="explore">Choisir mes plats</button></div><p class="fine week-start-note">Vos portions, votre budget, vos restrictions et votre équipement sont conservés. Les soirées thématiques repartent à zéro après une nouvelle semaine.</p><div class="week-start-secondary"><button class="text-link" data-preferences>Modifier mes préférences</button>${state.weekUndo?'<button class="text-link" data-undo-week>Annuler et retrouver ma semaine précédente</button>':''}</div></div>`;}

function generateNewWeek(){weekFlow.start();}

function explore(favorites){
 const result=desireResults(recipes,search,{favorites:favorites?state.favorites:null,course:courseFilter,theme:themeFilter,filter,price:perPortion,profile:state.onboarded?state.profile:null});
 const prices=currentOfferPrices();if(Object.keys(prices).length&&!result.intent.budget){const coverage=r=>Object.keys(r.items).filter(id=>prices[id]!==undefined).length/Object.keys(r.items).length;result.recipes.sort((a,b)=>coverage(b)-coverage(a));}
 const found=providerRecipeIds?result.recipes.slice().sort((a,b)=>{const ai=providerRecipeIds.indexOf(a.id),bi=providerRecipeIds.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi);}):result.recipes;
 const shown=favorites?found.slice(0,visibleRecipes):discoveryBatch(found,desireRound,visibleRecipes,desireSeen);
 if(!favorites)lastDiscoveryIds=shown.map(r=>r.id);
 const filtersBody=`<div class="filters course-filters">${[['all','Toute la table'],['main','Les plats'],['starter','Les entrées'],['dessert','Les desserts']].map(([id,label])=>`<button class="chip ${courseFilter===id?'active':''}" data-course-filter="${id}">${label}</button>`).join('')}</div><div class="filters">${[['all','Toutes les envies'],['veg','Végétarien'],['quick','25 min ou moins'],['budget','Petit budget']].map(([id,label])=>`<button class="chip ${filter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><label class="theme-filter">Une ambiance<select id="explore-theme"><option value="">Toutes les ambiances</option>${Object.entries(eventLabels).map(([id,name])=>`<option value="${id}" ${themeFilter===id?'selected':''}>${name}</option>`).join('')}</select></label>`;
 return `<div class="wrap inspiration-page"><section class="desire-intro forest-discovery"><div class="forest-discovery-copy"><div class="eyebrow">${favorites?'Vos coups de cœur':'L’inspiration, à votre goût'}</div><h1>${favorites?'À refaire.<br><em>Sans hésiter.</em>':'Une envie.<br><em>Un beau repas.</em>'}</h1><p>${favorites?'Les recettes que vous avez envie de retrouver.':'Crémeux, croustillant, réconfortant… Dites-nous ce qui vous ferait plaisir.'}</p><form id="desire-form" class="desire-form"><label class="sr-only" for="search-recipes">De quoi avez-vous envie?</label><div>${icon('search')}<input id="search-recipes" name="desire" placeholder="De quoi avez-vous envie ce soir?" maxlength="300" value="${esc(search)}" autocomplete="off"></div><button class="primary" ${desireBusy?'disabled':''}>${desireBusy?'On vous prépare des idées…':'Trouver l’inspiration'} ${icon('arrow')}</button></form><div class="desire-examples"><span>Et si on partait sur…</span>${[['Un soir italien','italien'],['Un beau poisson','poisson au citron'],['Végétal gourmand','végétarien réconfortant'],['Prêt en 25 min','repas rapide'],['Une soirée à deux','souper romantique']].map(([label,q])=>`<button data-desire="${q}" ${desireBusy?'disabled':''}>${label} ↗</button>`).join('')}</div>${storeInline()}</div><div class="forest-discovery-art" aria-hidden="true"><img src="assets/sauge-layers-cutout-v2.png" alt="" loading="lazy"></div></section>${fold('discovery-filters','Préciser mes envies',`${courseFilter==='all'?'Tous les services':courseFilter==='main'?'Plats':courseFilter==='starter'?'Entrées':'Desserts'}${filter!=='all'||themeFilter?' · filtres actifs':' · facultatif'}`,filtersBody)}<div class="discovery-results-head"><div><div class="eyebrow">${search?'Votre envie du moment':'La collection Sauge'}</div><h2>${search?'Voilà de quoi <em>vous régaler.</em>':'Qu’est-ce qui vous <em>tente?</em>'}</h2><p class="fine" role="status">${found.length} recette${found.length>1?'s':''} ${search?'pour cette recherche':'illustrées'}${state.onboarded?' · vos restrictions alimentaires sont prises en compte':''}${desireNotice?' · '+esc(desireNotice):''}</p></div>${!favorites?`<button class="secondary refresh-ideas" id="refresh-inspirations" ${desireBusy||!found.length?'disabled':''}>${icon('refresh')} D’autres idées</button>`:''}</div>${desireBusy?'<div class="inspiration-loading" role="status">On cherche de quoi vous mettre l’eau à la bouche…</div>':''}${shown.length?`<div class="recipe-grid discovery-grid">${shown.map(card).join('')}</div><div class="inspiration-bottom">${found.length>shown.length?`<button class="secondary" id="more-recipes">Voir davantage de recettes ${icon('arrow')}</button>`:''}${!favorites?'<button class="text-link" id="refresh-bottom">Renouveler les idées ↻</button>':''}</div>`:`<div class="empty"><h2>${favorites?'Votre carnet vous attend.':'On change un peu <em>d’inspiration?</em>'}</h2><p>${favorites?'Gardez une recette avec le cœur pour la retrouver ici.':'La collection actuelle n’a pas encore de recette correspondant à tous ces choix. Essayez une envie plus large ou retirez un filtre.'}</p><button class="primary" id="reset-filter">Toutes les inspirations ${icon('arrow')}</button></div>`}${search||filter!=='all'||themeFilter||courseFilter!=='all'?'<button class="text-link" id="clear-desire">Effacer ma recherche et mes filtres</button>':''}<p class="photo-disclaimer">${recipes.filter(r=>r.photoVerified).length} recettes illustrées · une photographie réelle distincte pour chaque plat. ${experienceGateway.connected?'Les suggestions du service connecté restent soumises à vos restrictions.':'Suggestions de notre collection.'}</p></div>`;
}

function calendarControls(p,inQuiz=false){
 const schedule=activeDays(p),count=dayCount(p);
 return `<div class="calendar-controls"><label class="weekend-switch"><input type="checkbox" ${inQuiz?'data-quiz-weekend':'id="weekend-toggle"'} ${p.weekend?'checked':''}><span>Inclure la fin de semaine</span><small>Samedi et dimanche</small></label>${!inQuiz?'<span class="fine">Décochez un jour où vous ne cuisinez pas.</span>':''}</div><div class="week-strip calendar-strip ${inQuiz?'quiz-calendar':''}" style="--day-count:${count}" aria-label="Journées du menu">${Array.from({length:count},(_,i)=>{const on=schedule.includes(i),id=state.ids[i];return `<div class="calendar-day ${on?'':'off'} ${!inQuiz&&selectedDay===i?'current':''}"><label><input type="checkbox" ${inQuiz?'data-quiz-day':'data-plan-day'}="${i}" ${on?'checked':''}><span>${days[i]}</span></label>${inQuiz?`<small>${on?'À planifier':'Rien à prévoir'}</small>`:`<button data-day="${i}" aria-pressed="${selectedDay===i}" ${on?'':'disabled'}><small>${on?(id?esc(dish(id)?.name.split(',')[0]||'À composer'):'À composer'):'Journée libre'}</small>${state.locked[i]&&on?'<span class="day-lock">◆ Conservé</span>':''}${p.events?.[i]&&on?`<span class="day-event">${eventLabels[p.events[i].theme]}</span>`:''}</button>`}</div>`;}).join('')}</div>`;
}
function menu(){
 if(!state.ids.length)return emptyPlan();
 const p=state.profile,scheduled=activeDays(p),lunchTotal=scheduled.reduce((n,i)=>n+lunchForDay(p,i),0),locked=scheduled.filter(i=>state.locked[i]).length;
 if(!scheduled.includes(selectedDay))selectedDay=scheduled[0]??0;
 const intro=`<div class="wrap">${title('Du quotidien aux grandes tablées','Cette semaine,<br><em>on se régale.</em>',`${scheduled.length} journée${scheduled.length>1?'s':''} planifiée${scheduled.length>1?'s':''} · ${lunchTotal} portions lunch · aucun plat répété`,`<button class="secondary" data-start>Mes préférences</button><button class="secondary" data-new-week>Nouvelle semaine</button><button class="primary" id="regenerate">Revoir mes choix ${icon('refresh')}</button>`)}${storeInline()}${calendarControls(p)}${planGaps()}`;
 if(!scheduled.length)return intro+`<div class="empty"><h2>Une semaine <em>à votre rythme.</em></h2><p>Cochez une journée pour y ajouter un repas. Les jours libres ne génèrent aucun achat.</p></div></div>`;
 const r=dish(state.ids[selectedDay]);if(!r)return intro+'<div class="empty"><h2>Cette journée reste à composer.</h2><p>Les autres repas et leur épicerie sont conservés. Ajustez le thème ou la durée de cette journée.</p><button class="secondary" data-occasion="'+selectedDay+'">Ajuster cette journée</button><button class="primary" data-start>Mes préférences</button></div></div>';
 const lunch=lunchForDay(p,selectedDay),people=supperPeople(p,selectedDay),e=p.events[selectedDay],total=cost();
 const occasion=e?`<section class="occasion-ribbon"><div><span class="eyebrow">Une place à part dans la semaine</span><h2>${eventLabels[e.theme]}</h2><p>${people} convive${people>1?'s':''} · ${e.starter?'Entrée · ':''}Plat${e.dessert?' · Dessert':''}</p></div><button class="secondary" data-occasion="${selectedDay}">Modifier l’occasion</button></section>`:`<div class="occasion-prompt"><span>Et si ${days[selectedDay].toLowerCase()} devenait une occasion?</span><button class="text-link" data-occasion="${selectedDay}">Romantique, thématique, brunch… <span class="plus-badge">✦ Plus</span> ${icon('arrow')}</button></div>`;
 const sideCards=['starter','dessert'].filter(kind=>e?.[kind]&&state.courses[selectedDay]?.[kind]).map(kind=>{const extra=dish(state.courses[selectedDay][kind]);return `<article class="event-course"><button data-recipe="${extra.id}" data-recipe-day="${selectedDay}" class="course-photo">${photo(extra)}</button><div><div class="eyebrow">${kind==='starter'?'Pour commencer':'La touche sucrée'}</div><h3>${extra.name}</h3><p class="fine">${people} portions · ${extra.time} min</p><div class="actions"><button class="text-link" data-recipe="${extra.id}" data-recipe-day="${selectedDay}">La recette ${icon('arrow')}</button><button class="course-swap" data-swap="${selectedDay}" data-kind="${kind}" aria-label="Changer ${kind==='starter'?'l’entrée':'le dessert'}">${icon('refresh')}</button></div></div></article>`;}).join('');
 return intro+occasion+`<section class="featured-dish"><div class="feature-photo">${photo(r,'','eager')}<span class="photo-tag">${days[selectedDay]} · ${r.tag}</span></div><div class="feature-copy"><div class="eyebrow">Le plat ${e?'de votre occasion':'du '+days[selectedDay].toLowerCase()}</div><h2>${r.name}</h2><p>${r.sub}</p><div class="dish-meta"><span>${icon('clock')} ${r.time} min${r.longCook?' dont cuisson longue':''}</span><span>${r.level===1?'Facile':'Un peu de pratique'}</span></div><div class="small-stat"><div><strong>${people+lunch}</strong><span>${people} à table + ${lunch} lunch</span></div><div><strong>${recipePrice(r)}</strong><span>/ portion standard, estimation</span></div></div><div class="actions"><button class="primary" data-recipe="${r.id}" data-recipe-day="${selectedDay}">Voir la recette ${icon('arrow')}</button><details class="action-menu meal-actions"><summary>Modifier ce repas</summary><button class="secondary" data-swap="${selectedDay}" data-kind="main">${icon('refresh')} Remplacer</button><button class="secondary rescue-trigger" data-rescue="${selectedDay}">Sauve mon souper ${icon('refresh')}</button><button class="text-link" data-move="${selectedDay}">Déplacer ce plat vers une autre journée →</button><button class="keep-meal ${state.locked[selectedDay]?'kept':''}" data-lock="${selectedDay}" aria-pressed="${!!state.locked[selectedDay]}">${state.locked[selectedDay]?'◆ Plat conservé à la prochaine proposition':'◇ Conserver ce plat dans mon menu'}</button></details></div></div></section>${e?`<div class="occasion-tools"><button class="primary" data-timeline="${selectedDay}">Recevoir sans stress ${icon('clock')}</button><button class="secondary" data-menu-card="${selectedDay}">Le menu à partager</button></div>`:''}${lunchUpgrade(r,selectedDay)}${lunch?lunchPanel(r,selectedDay):''}${sideCards?`<div class="event-courses">${sideCards}</div><p class="fine mt">Entrées et desserts : portions pour les convives, sans portions lunch supplémentaires. Les temps affichés concernent chaque recette.</p>`:''}${locked?`<p class="fine mt">${locked} plat${locked>1?'s':''} conservé${locked>1?'s':''}. Les autres jours restent modifiables.</p>`:''}${total>p.budget?`<div class="info-strip warning">Le menu complet, occasions comprises, dépasse le budget visé de ${money(total-p.budget)}. Les filtres et l’absence de doublon restent respectés. Ajustez le budget, les journées ou les inclusions.</div>`:''}<details class="detail-fold"><summary>Budget et préparation de la semaine</summary><div class="plan-bottom"><section class="panel"><div class="eyebrow">L’épicerie, sans surprise</div><div class="budget-amount">${money(total)} <small>/ ${money(p.budget)} visés</small></div><div class="meter"><span style="width:${Math.min(100,total/p.budget*100)}%"></span></div><p class="fine">${shopping().some(x=>x.priceKnown===false)?"Estimation partielle : certains ingrédients personnels restent à chiffrer. ":""}Tous les plats, entrées et desserts choisis sont regroupés. Le stock est déduit une seule fois. Estimation des ingrédients utilisés, hors formats complets achetés.</p><button class="primary" data-go="list">Ma liste d’épicerie ${icon('bag')}</button></section><section class="panel"><div class="eyebrow">Un peu d’avance</div><h3>Prendre le temps.<br>Puis <em>en profiter.</em></h3><p class="fine">Une mise en place liée aux recettes de votre menu, occasions comprises.</p><button class="text-link" id="archive-week">Garder cette semaine dans mon historique →</button><button class="secondary" id="weekly-prep">Ma préparation ${icon('arrow')}</button><div class="summary-tags"><span>${scheduled.length} plats différents</span><span>${lunchTotal} portions lunch</span></div></section></div></details><details class="detail-fold adjustment-fold"><summary><span>Un changement d’envie?<small>Des raccourcis pour ajuster le menu</small></span><span class="fold-symbol">+</span></summary><div class="fold-body"><form id="adjust-form" class="chat-form"><input aria-label="Ajuster le menu" placeholder="Ex. : plus rapide, végétarien…" maxlength="200"><button aria-label="Appliquer la demande">${icon('arrow')}</button></form><p class="fine mt">Commandes locales : « végétarien », « plus rapide », « moins cher », « sans poulet ». Les demandes libres nécessiteront l’IA connectée.</p></div></details>${chatAnswer?`<p class="fine" role="status">${esc(chatAnswer)}</p>`:''}</div>`;
}

function list(){
 if(!state.ids.length)return emptyPlan();
 const rows=shopping(),all=rows.filter(r=>r.needed>0),extras=state.extraItems;
 const count=all.length+extras.length,n=all.filter(r=>state.checked[r.id]).length+extras.filter(r=>state.checked['extra-'+r.id]).length;
 const missing=extras.filter(r=>r.estimatedPrice===null).length+all.filter(r=>r.priceKnown===false).length;
 const stockUsed=rows.filter(r=>r.total>r.needed);
 return `<div class="wrap">${title('Tout est regroupé','L’essentiel. <em>Rien de plus.</em>',`${all.length} ingrédients du menu · ${extras.length} achat${extras.length>1?'s':''} ajouté${extras.length>1?'s':''} · ${n} coché${n>1?'s':''}`,`<button class="secondary" data-go="pantry">Ajuster mon inventaire</button>`)}${planGaps()}${basketPanel()}<div class="shop-layout"><section>${ingredientCategories.map(c=>`<h2 class="category-title">${c}</h2>${all.filter(r=>r.category===c).map(r=>`<div class="shopping-row ${state.checked[r.id]?'checked':''}"><input id="check-${r.id}" type="checkbox" data-check="${r.id}" ${state.checked[r.id]?'checked':''}><label for="check-${r.id}">${r.name}</label><span class="qty">${quantityLabel(r.id,r.needed)}</span><span class="cost">${r.priceKnown===false?"À estimer":money(r.needed*r.price)}</span></div>`).join('')||'<p class="fine">Tout est déjà à la maison.</p>'}`).join('')}<h2 class="category-title">Mes autres achats</h2>${extras.map(r=>`<div class="shopping-row ${state.checked['extra-'+r.id]?'checked':''}"><input id="check-extra-${r.id}" type="checkbox" data-check="extra-${r.id}" ${state.checked['extra-'+r.id]?'checked':''}><label for="check-extra-${r.id}">${esc(r.name)}</label><span class="qty">${esc(r.quantity)}</span><span class="cost">${r.estimatedPrice===null?'Sans prix':money(r.estimatedPrice)}</span><button class="remove-extra" data-remove-extra="${r.id}" aria-label="Retirer ${esc(r.name)}">×</button></div>`).join('')||'<p class="fine">Du pain, du lait, le café… Ajoutez ce qui manque pour la maison.</p>'}<details class="detail-fold"><summary>Ajouter un achat pour la maison</summary><form id="extra-form" class="extra-form"><label>Article<input id="extra-name" maxlength="60" placeholder="Ex. : pain" required></label><label>Quantité<input id="extra-quantity" maxlength="30" placeholder="Ex. : 1 miche"></label><label>Prix total estimé ($)<input id="extra-price" type="number" min="0" max="10000" step="0.01" placeholder="Facultatif"></label><button class="secondary" type="submit">Ajouter +</button></form></details>${fold('stock-used','Ce qui est déjà à la maison',`${stockUsed.length} ingrédient${stockUsed.length>1?'s':''} déduit${stockUsed.length>1?'s':''} du menu`,`<p class="fine">Les quantités ci-dessous sont utilisées dans le menu et ne sont pas à racheter.</p>${stockUsed.map(r=>`<div class="ingredient-line"><span>${r.name}</span><span>${quantityLabel(r.id,r.total-r.needed)}</span></div>`).join('')||'<p class="fine">Aucun stock disponible n’est encore déduit. Complétez votre garde-manger pour ajuster la liste.</p>'}`)}</section><aside class="panel aside-panel"><div class="eyebrow">Votre semaine en bref</div><h3>Le panier bien pensé.</h3><div class="total-row"><span>Ingrédients du menu</span><span>${money(planCost(state.ids,state.profile,{},state.courses))}</span></div><div class="total-row"><span>Déjà dans l’inventaire</span><span>− ${money(planCost(state.ids,state.profile,{},state.courses)-cost())}</span></div><div class="total-row"><span>Menu : reste à acheter</span><span>${money(cost())}</span></div>${extras.length?`<div class="total-row"><span>Autres achats renseignés</span><span>+ ${money(extraCost())}</span></div>`:''}<div class="total-row big"><span>${missing?'Total partiel':'À acheter'}</span><span>${money(cost()+extraCost())}</span></div>${missing?`<p class="fine warning">${missing} achat${missing>1?'s':''} sans prix ${missing>1?'ne sont pas inclus':'n’est pas inclus'} dans ce total.</p>`:''}<div class="meter"><span style="width:${count?n/count*100:100}%"></span></div><p class="fine">${n} / ${count} articles cochés.<br>Le budget du menu couvre les journées cochées, leurs lunchs et leurs occasions; les autres achats s’y ajoutent. Prix indicatifs, hors formats d’emballage.</p><button class="primary" id="download">Télécharger la liste ↓</button><button class="secondary" id="print">Imprimer</button><button class="text-link mt" id="uncheck">Tout décocher</button></aside></div></div>`;
}

function pantry(){return `<div class="wrap">${title('La première épicerie est chez vous','Un garde-manger <em>bien pensé.</em>','Indiquez les quantités disponibles. Votre liste d’épicerie se recalcule automatiquement.',`<button class="secondary" data-preferences>Mes préférences</button><button class="primary" data-new-week>Nouvelle semaine</button>`)}<div class="shop-layout"><section>${pantrySummary()}<div class="priority-stock"><div class="eyebrow">À utiliser en premier</div><p class="fine">Signalez les ingrédients que vous souhaitez cuisiner en priorité. Les quantités doivent aussi être saisies dans l’inventaire. La préférence sera utilisée à la prochaine proposition de menu.</p><div class="filters">${Object.entries(ingredients).map(([id,r])=>`<button class="chip ${state.pantryPriority.includes(id)?'active':''}" data-priority="${id}" aria-pressed="${state.pantryPriority.includes(id)}">${r[0]}</button>`).join('')}</div></div>${ingredientCategories.map(c=>`<h2 class="category-title">${c}</h2>${Object.entries(ingredients).filter(([,r])=>r[3]===c).map(([id,r])=>`<div class="shopping-row"><label for="stock-${id}">${r[0]}</label><input id="stock-${id}" type="number" min="0" max="100000" data-stock="${id}" value="${state.pantry[id]||0}"><span class="fine">${r[1]}</span><label class="expiry-label">Date à surveiller<input type="date" data-expiry="${id}" value="${esc(state.expiry[id]||'')}"></label></div>`).join('')}`).join('')}</section><aside class="panel aside-panel"><div class="eyebrow">Le bon réflexe</div><h3>Utiliser avant d’acheter.</h3><p class="fine">Un même ingrédient utilisé dans plusieurs recettes est regroupé. Votre stock est déduit une seule fois du total de la semaine.</p><div class="total-row big"><span>En stock</span><span id="stock-count">${Object.values(state.pantry).filter(n=>n>0).length} ingrédients</span></div><p class="fine">Mettez les quantités à jour après avoir cuisiné. Les stocks ne sont pas décrémentés automatiquement.</p><button class="primary" data-go="list">Voir ma liste ajustée ${icon('arrow')}</button></aside></div></div>`;}
function trustSection(){return `<section class="sauge-trust wrap" aria-label="Vos repères de confiance"><div class="sauge-trust-heading"><span class="handwritten">Bon dans l’assiette. Clair dans la tête.</span><h2>Le plaisir, avec<br><em>les idées claires.</em></h2></div><div class="sauge-trust-grid">${[['Vous gardez la main','Vous choisissez vos plats avant de valider. Rien ne remplace votre souper sans votre choix.'],['Votre carnet, à vous','Vos recettes personnelles sont privées par défaut. Vous choisissez celles à proposer à la communauté.'],['Des estimations annoncées','Coûts indicatifs, portions et ingrédients visibles. Aucune économie garantie ni faux rabais.'],['Sans carte pour explorer','Découvrez le parcours et le compte démo. Aucun paiement ni essai facturé dans cet aperçu.']].map(([label,text])=>`<article><span class="sauge-trust-mark" aria-hidden="true">${icon('check')}</span><h3>${label}</h3><p>${text}</p></article>`).join('')}</div></section>`;}
function plusTeaser(){return `<section class="sauge-plan-teaser wrap"><div><span class="handwritten">Un peu plus de liberté.</span><h2>7 soupers gratuits.<br><em>Plus pour le reste de la journée.</em></h2><p>Vos soupers de la semaine sont gratuits. Plus va plus loin : dîners, déjeuners, nouvelles recettes avec les ingrédients restants et organisation des soirées avec invités.</p><button class="text-link" data-go="plans">Comparer Gratuit et Plus ${icon('arrow')}</button><p class="fine">Formules proposées pour le lancement. Aucune vente activée dans cet aperçu.</p></div><div class="sauge-plan-mini"><article><small>SAUGE GRATUIT</small><strong>Vos 7 soupers.</strong><p>7 soupers par semaine, recettes, portions, préférences, budget indicatif et liste d’épicerie regroupée.</p><span>0 $</span></article><article><small>✦ SAUGE PLUS</small><strong>Toute votre journée.</strong><p>Dîners, déjeuners, ingrédients réutilisés et occasions avec invités : la planification au-delà du souper.</p><span>9,99 $ <small>/ mois proposé</small></span></article></div></section>`;}
function plans(){const comparisons=[['Collection, favoris et recettes privées','Inclus','Inclus'],['Portions, restrictions et liste regroupée','Inclus','Inclus'],['Soupers de la semaine','7 soupers','7 soupers'],['Dîners et déjeuners planifiés','—','Prévu au lancement'],['Autres repas avec les ingrédients restants','Gestion manuelle','Planification prévue avec Plus'],['Lunch du même plat','Inclus','Inclus'],['Transformer le lunch quand une variante existe','—','✦ Plus'],['Soirées avec entrée, plat et dessert','Plat simple','✦ Plus'],['Préparation et quantités des soupers','Inclus','Inclus'],['Organisation des invités et heure de service','—','✦ Plus'],['Favoris, historique et préférences','Inclus','Inclus']];return `<div class="wrap sauge-plans">${title('Choisissez le rythme qui vous ressemble','Bien manger.<br><em>Un peu plus simplement.</em>','Planifiez vos 7 soupers gratuitement. Choisissez Plus pour organiser les autres repas et vos occasions, en réutilisant ce qui reste.')}<p class="sauge-launch-note">Formules proposées pour le lancement · Aucun paiement ni essai facturé dans cet aperçu.</p><div class="pricing"><section class="panel"><div class="eyebrow">Pour tous les soupers</div><h2>Sauge Gratuit</h2><div class="price">0 $</div><p>Tout le nécessaire pour vos soupers, sans abonnement.</p><ul><li>Découvrir la collection et garder vos favoris</li><li>Enregistrer vos recettes privées dans un compte</li><li>Prévoir jusqu’à 7 soupers par semaine gratuitement</li><li>Adapter les portions et réserver le même plat en lunch</li><li>Restrictions, allergies, équipements et budget indicatif inclus</li></ul><button class="secondary full" data-go="explore">Je découvre les plats</button></section><section class="panel premium"><span class="sauge-plan-ribbon">Toute la semaine, à votre façon</span><div class="eyebrow">Au-delà du souper</div><h2>Sauge Plus</h2><div class="price">9,99 $ <small>/ mois</small></div><p class="fine">Ou 79,99 $ / an · CAD, avant taxes · tarifs proposés.</p><ul><li>Planifier les dîners et les déjeuners en plus des 7 soupers — prévu au lancement</li><li>Créer un autre repas à partir des ingrédients restants — variantes lunch déjà en démonstration</li><li>Organiser les invités, soirées romantiques ou thématiques, entrées et desserts</li><li>Coordonner les préparations et l’heure de service des occasions</li><li>Réunir les repas Plus et leurs ingrédients dans la planification</li></ul><button class="primary full" data-trial-info>Voir le parcours Plus</button><p class="fine">Essai de 14 jours sans carte proposé au lancement. Aucun essai ne démarre ici.</p></section></div><section class="sauge-plus-value"><span class="handwritten">Ce qui change au quotidien</span><h2>Pourquoi choisir <em>Plus?</em></h2><div><article><small>LE DIMANCHE</small><h3>Du matin au soir, une organisation qui suit.</h3><p>Les 7 soupers restent gratuits. Plus ajoutera la planification dédiée des déjeuners et des dîners; ces créneaux restent à développer avant le lancement.</p></article><article><small>LE LENDEMAIN MIDI</small><h3>Les ingrédients restants deviennent un autre repas.</h3><p>Un reste de poulet, de riz ou de légumes sert de point de départ à un autre plat. Les variantes lunch existent déjà; la réutilisation automatique entre plusieurs recettes reste à développer.</p></article><article><small>QUAND ON REÇOIT</small><h3>Vous profitez aussi de votre soirée.</h3><p>Entrée, plat, dessert et déroulé de préparation au même endroit. Vous gardez le choix des recettes et le contrôle des quantités.</p></article></div><p class="fine">L’intérêt dépend de votre usage : si vos 7 soupers et des portions du même plat à réchauffer vous suffisent, Gratuit reste complet. Aucun gain de temps ou montant d’économie n’est garanti.</p></section><details class="detail-fold sauge-comparison"><summary><span>Comparer les fonctions en détail<small>Ce qui est prévu dans chaque formule</small></span><span class="fold-symbol">+</span></summary><div class="fold-body"><div class="sauge-table-scroll"><table><caption class="sr-only">Comparaison des formules prévues Sauge Gratuit et Sauge Plus</caption><thead><tr><th scope="col">Pour votre cuisine</th><th scope="col">Gratuit</th><th scope="col">Plus</th></tr></thead><tbody>${comparisons.map(([label,free,plus])=>`<tr><th scope="row">${label}</th><td>${free}</td><td>${plus}</td></tr>`).join('')}</tbody></table></div></div></details><section class="sauge-pricing-faq"><h2>Avant de <em>choisir.</em></h2>${[['Est-ce que je dois payer pour essayer?','Non. L’aperçu et le compte démo s’explorent sans carte. Les abonnements ne sont pas encore vendus. Le parcours proposé prévoit un essai Plus de 14 jours sans carte au lancement.'],['Pourquoi certains outils sont-ils ouverts dans cet aperçu?','L’aperçu vous permet de parcourir les fonctions avant le lancement. Les transformations lunch et l’organisation des occasions illustrent les accès Plus. Les dîners, déjeuners et la réutilisation automatique des ingrédients sont prévus au lancement : pas encore un service actif. Le tableau décrit les formules prévues, pas toutes les limites actuellement appliquées au prototype.'],['Mes recettes sont-elles publiées automatiquement?','Non. Les recettes personnelles restent privées par défaut. Une proposition à la communauté passe par une approbation et une copie publique séparée.'],['Les prix et les rabais sont-ils en direct?','Pas encore. Les montants affichés sont indicatifs. Les données de détaillants et l’IA générative restent à connecter; elles ne sont pas présentées comme des services actifs de l’abonnement.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>${trustSection()}<div class="sauge-launch-note">Votre compte réel fonctionne lorsque Supabase est configuré; sans configuration, l’application reste en mode invité sur cet appareil. Les formules seront mises en vente seulement après la connexion des services et les validations de lancement.</div></div>`;}


function openModal(html){document.querySelector('#modal-content').innerHTML=html;const modal=document.querySelector('#modal');if(!modal.open)modal.showModal();modal.scrollTop=0;bindModal();}

function cookingText(text){return esc(text).replace(/(-?\d+(?:[.,]\d+)?)\s*°\s*C\b(?!\s*\([^)]*°\s*F)/g,(_,value)=>{const c=Number(value.replace(',','.'));return value+' °C ('+new Intl.NumberFormat('fr-CA',{maximumFractionDigits:1}).format(c*9/5+32)+' °F)';});}
function cookingSafety(r){
 const targets=[];
 if(r.items.chicken)targets.push('Poulet : 74 °C');
 if(r.items.groundBeef)targets.push('Bœuf haché : 71 °C');
 if(r.items.beef)targets.push('Bœuf entier à point : 71 °C');
 if(r.items.pork)targets.push('Porc : 71 °C');
 if(r.items.salmon||r.items.whiteFish||r.items.wholeFish)targets.push('Poisson : 70 °C');
 if(r.items.shrimp||r.items.wholeShrimp)targets.push('Crevettes : 74 °C');
 if(r.items.egg)targets.push('Préparation à base d’œufs : 74 °C');
 return targets.length?'<div class="cooking-temperature"><strong>'+targets.map(cookingText).join(' · ')+' à cœur</strong><p>Vérifier au thermomètre dans la partie la plus épaisse, sans toucher un os. Le temps seul ne suffit pas à confirmer la cuisson.</p></div>':'';
}

function showRecipe(id,day=null,scale=null){
 const r=dish(id);if(!r)return;recipeScale=scale;
 const planned=weekEntries(state.ids,state.profile,state.courses).find(e=>e.id===id&&(day===null||e.index===day));
 recipeDay=day??planned?.index??activeDays(state.profile)[0]??0;
 const p=state.profile,amountProfile=planned?p:{...p,weekend:true,activeDays:[0,1,2,3,4,5,6],events:{}},lunch=r.course==='main'?lunchForDay(amountProfile,recipeDay):0,people=supperPeople(amountProfile,recipeDay),quantity=scale??(r.course==='main'?servingsForDay(amountProfile,recipeDay):courseServings(amountProfile,recipeDay));
 openModal(`<div class="modal-image">${photo(r,'','eager')}</div><div class="modal-body"><div class="eyebrow">${r.tag} · ${r.time} min au total</div><h2>${r.name}</h2><p class="muted">${r.sub}</p><div class="summary-tags"><span>${people+lunch} portions</span><span>${people} à table + ${lunch} lunch</span><span>${r.prepTime} min de préparation</span><span>${r.cookTime} min de cuisson</span>${r.passiveTime?`<span>${r.passiveTime} min de repos / refroidissement</span>`:''}<span>${r.level===1?'Facile':'Un peu de pratique'}</span></div><p class="fine">${sizeLabel(p)} · ${recipePrice(r)} par portion standard estimée.</p><div class="actions"><button class="secondary" data-add="${id}">Mettre au menu</button></div><div class="recipe-columns"><section><h3>Les ingrédients du souper</h3><label class="recipe-scale">Nombre de portions<input id="recipe-scale" data-id="${r.id}" data-factor="${p.portionSize==='generous'?1.25:p.portionSize==='small'?.75:1}" type="number" min="1" max="36" step="1" value="${Math.max(1,Math.round(quantity/(p.portionSize==='generous'?1.25:p.portionSize==='small'?.75:1)))}"></label>${Object.entries(r.items).map(([key,q])=>`<div class="ingredient-line"><span>${ingredients[key][0]}</span><span>${quantityLabel(key,q*(scale===null&&planned&&r.course==='main'&&lunchVariant(r,p)?courseServings(amountProfile,recipeDay):quantity))}</span></div>`).join('')}<p class="fine mt">${r.items.rice||r.items.pasta?'Riz et pâtes : poids sec. ':''}${r.items.lentils||r.items.chickpea?'Légumineuses : poids cuit et égoutté. ':''}Sel, poivre et eau au besoin. Les mesures de cuisine sont approximatives; le poids ou volume de référence reste entre parenthèses. Tasse de 250 ml, c. à soupe de 15 ml, c. à thé de 5 ml.</p><div class="recipe-equipment"><strong>À sortir avant de commencer</strong><p>${r.equipment.map(id=>equipmentLabels[id]).join(' · ')} · couteau · planche · thermomètre de cuisson</p></div><p class="fine mt">${r.unverifiedIngredients?'Certains ingrédients personnels ne sont pas référencés : allergènes à vérifier. ':''}${r.allergens.length?`Allergènes déclarés dans cette recette : <strong>${r.allergens.map(id=>allergenLabels[id]).join(', ')}</strong>.`:'Aucun des allergènes suivis n’est déclaré dans les ingrédients de cette recette.'} Vérifiez les produits utilisés et les traces possibles.</p></section><section><h3>À vous de jouer.</h3><ol class="steps">${r.steps.map(t=>`<li>${cookingText(t)}</li>`).join('')}</ol><div class="cook-tip"><strong>Le petit geste qui change tout</strong><p>${r.textureTip}</p></div></section></div>${planned&&lunch?lunchPanel(r,recipeDay):''}${cookingSafety(r)}${recipeNotebook(r)}<div class="practical-details">${fold('recipe-prep','Prendre de l’avance','Les gestes à faire avant le souper',`<p>${r.prepAhead}</p>`)}${fold('recipe-lunch','Le lunch et le réchauffage',r.coldLunch?'Bon aussi froid, en gardant la chaîne du froid':'À réchauffer pour ce menu',`<p>${r.lunchTip}</p><p><strong>Pour réchauffer :</strong> ${r.reheat}</p>`)}${fold('recipe-storage','Conservation et congélation','Les bons repères pour réserver vos portions',`<p>${r.freezer}</p><p>Répartissez rapidement les restes dans des contenants peu profonds. Réfrigérez dans les deux heures, à 4 °C ou moins. Consommez sous deux ou trois jours, ou congelez. Réchauffez jusqu’à 74 °C au cœur.</p>`)}</div><p class="photo-disclaimer">${r.accountRecipe?'Recette proposée par '+esc(r.creator)+'. '+(r.userPhoto?'Photographie fournie par son auteur.':'Photo facultative, non fournie.'):'Photographie réelle correspondant au plat; le dressage peut varier.'} Temps indicatifs, à adapter à votre matériel et à la cuisson réelle.</p></div>`);
}

function preservePlanOptions(except=null){return {locked:Array.from({length:dayCount(state.profile)},(_,i)=>i===except?null:state.ids[i]||null),fixedCourses:Object.fromEntries(Object.entries(state.courses).filter(([i])=>Number(i)!==except)),priority:state.pantryPriority,recent:state.history.slice(0,3).flatMap(h=>h.ids||[]),offerPrices:currentOfferPrices()};}
function applySchedule(p,except=null){
 p=normalizeProfile(p);
 const result=activeDays(p).length?generatePlan(p,state.pantry,state.rotation,preservePlanOptions(except)):{ids:Array(dayCount(p)).fill(null),courses:{}};
 if(result.error){toast(result.error);return false;}
 state.profile=p;state.ids=result.ids;state.courses=result.courses||{};state.checked={};state.prepChecks={};if(except!==null)delete state.locked[except];for(const i of Object.keys(state.locked))if(!activeDays(p).includes(Number(i)))delete state.locked[i];
 if(!activeDays(p).includes(selectedDay))selectedDay=activeDays(p)[0]??0;
 save();go('menu');return true;
}
function setPlanDay(index,on){const p=structuredClone(state.profile);p.activeDays=on?[...new Set([...p.activeDays,index])]:p.activeDays.filter(i=>i!==index);if(!applySchedule(p,index))render();}
function setWeekend(on){const p=structuredClone(state.profile);p.weekend=on;p.activeDays=on?[...new Set([...p.activeDays,5,6])]:p.activeDays.filter(i=>i<5);if(!applySchedule(p))render();}
function showOccasion(index){if(!hasPlus()){showPlusFeature('occasion');return;}occasionDraft={index,enabled:true,event:structuredClone(state.profile.events[index]||{theme:index===6?'brunch':'romantic',starter:true,dessert:true,people:state.profile.people,maxTime:60})};renderOccasion();}
function renderOccasion(){
 const {index,enabled,event:e}=occasionDraft;
 openModal(`<div class="cook-view occasion-editor"><div class="eyebrow">${days[index]} prend une autre saveur</div><h2>Une soirée.<br><em>À votre image.</em></h2><label class="occasion-enabled"><input id="occasion-enabled" type="checkbox" ${enabled?'checked':''}> Prévoir une occasion pour cette journée</label><div class="occasion-themes">${Object.entries(eventLabels).map(([id,label])=>`<button class="theme-choice ${e.theme===id?'selected':''}" data-theme="${id}" aria-pressed="${e.theme===id}"><img src="assets/${eventImages[id]}.jpg" alt="" loading="lazy"><span>${label}</span><b aria-hidden="true">${e.theme===id?'✓':''}</b></button>`).join('')}</div><div class="occasion-fields"><label>Convives à table<input id="occasion-people" type="number" min="1" max="12" value="${e.people}"></label><label>Temps maximum par recette<select id="occasion-time">${[25,40,60,90,180].map(n=>`<option value="${n}" ${e.maxTime===n?'selected':''}>${n} minutes</option>`).join('')}</select></label></div><label class="service-time">Heure souhaitée pour passer à table<input id="occasion-service" type="time" value="${e.service||'19:00'}"></label><div class="occasion-inclusions"><label><input id="occasion-starter" type="checkbox" ${e.starter?'checked':''}><span>Une entrée<small>Pour ouvrir l’appétit</small></span></label><label><input type="checkbox" checked disabled><span>Le plat principal<small>Toujours inclus</small></span></label><label><input id="occasion-dessert" type="checkbox" ${e.dessert?'checked':''}><span>Un dessert<small>Pour finir en douceur</small></span></label></div><p class="fine">Votre régime, vos allergènes déclarés et vos équipements restent respectés. Les invités et les inclusions sont comptés dans l’épicerie et dans le budget du menu. Le temps indiqué est celui de chaque recette, pas de la soirée complète.</p><div id="occasion-error" role="alert"></div><button class="primary full" id="occasion-save">Composer cette occasion ${icon('arrow')}</button></div>`);
}
function saveOccasion(){
 if(!hasPlus()){showPlusFeature('occasion');return false;}if(!occasionDraft)return false;
 const p=structuredClone(state.profile),{index,enabled,event:e}=occasionDraft;
 e.service=document.querySelector('#occasion-service')?.value||e.service||'19:00';
 if(enabled)p.events[index]=structuredClone(e);else delete p.events[index];
 if(index>=5)p.weekend=true;if(!p.activeDays.includes(index))p.activeDays.push(index);
 const result=generatePlan(normalizeProfile(p),state.pantry,state.rotation,preservePlanOptions(index));
 if(result.error){pendingPartial={result,profile:normalizeProfile(p),pantry:structuredClone(state.pantry)};document.querySelector('#occasion-error').innerHTML=diagnosticHtml(result);bindDiagnostics();return;}
 state.profile=normalizeProfile(p);state.ids=result.ids;state.courses=result.courses||{};delete state.locked[index];state.checked={};state.prepChecks={};selectedDay=index;save();go('menu');toast(enabled?'Votre occasion est composée. L’épicerie est à jour.':'La journée retrouve un menu sans occasion.');
}
function replaceSelection(id,index,kind='main'){
 if(!activeDays(state.profile).includes(index)){toast('Cochez d’abord cette journée dans le planning.');return;}
 if(kind!=='main'&&!state.profile.events[index]?.[kind]){toast('Ajoutez cette inclusion dans les réglages de l’occasion.');return;}
 if(!eligibleRecipes(state.profile,index,kind,{manual:true}).some(r=>r.id===id)){toast('Cette recette ne correspond pas aux choix de cette journée.');return;}
 const duplicate=weekEntries(state.ids,state.profile,state.courses).find(entry=>entry.id===id&&(entry.index!==index||entry.course!==kind));
 if(duplicate){toast('Ce plat est déjà prévu '+days[duplicate.index].toLowerCase()+'. Choisissez une autre recette pour garder un menu sans répétition.');return;}
 if(kind==='main')state.ids[index]=id;else{state.courses[index]??={};state.courses[index][kind]=id;}
 state.checked={};state.prepChecks={};selectedDay=index;save();go('menu');toast('Recette remplacée. Quantités, budget et épicerie sont à jour.');
}
function showSwap(index,kind='main',order='price',limit=6){
 const current=kind==='main'?state.ids[index]:state.courses[index]?.[kind];
 const used=new Set(weekEntries(state.ids,state.profile,state.courses).filter(e=>e.id!==current).map(e=>e.id));
 const allOptions=eligibleRecipes(state.profile,index,kind,{manual:true}).filter(r=>r.id!==current&&!used.has(r.id)).sort((a,b)=>order==='time'?a.time-b.time||perPortion(a)-perPortion(b):order==='rating'?(b.ratingAverage||0)-(a.ratingAverage||0)||a.time-b.time:perPortion(a)-perPortion(b)||a.time-b.time),options=allOptions.slice(0,limit);
 openModal(`<div class="cook-view"><div class="eyebrow">Sans doublon. À votre goût.</div><h2>Une autre envie<br>pour <em>${days[index].toLowerCase()}?</em></h2><p class="fine">Ces ${kind==='main'?'plats':kind==='starter'?'entrées':'desserts'} respectent vos filtres, l’équipement et le thème éventuel. Les recettes déjà prévues ailleurs ne sont pas proposées.</p><label class="swap-sort">Classer les choix<select id="swap-sort"><option value="price" ${order==='price'?'selected':''}>Les plus économiques</option><option value="time" ${order==='time'?'selected':''}>Les plus rapides</option><option value="rating" ${order==='rating'?'selected':''}>Les mieux évalués</option></select></label><p class="fine">Vous choisissez le remplacement : aucun changement automatique. Temps et budget de cette journée respectés.</p><div class="swap-list">${options.map(r=>`<button class="swap-option" data-replace="${r.id}" data-index="${index}" data-replace-kind="${kind}">${photo(r)}<span><strong>${r.name}</strong><small>${r.time} min · ${recipePrice(r)} / portion</small></span></button>`).join('')||'<p class="info-strip">Aucune autre recette différente ne convient. Changez le thème, les équipements ou un filtre pour élargir le choix.</p>'}</div>${allOptions.length>limit?'<button class="secondary" id="swap-more">Voir davantage de choix</button>':''}</div>`);document.querySelector('#swap-sort')?.addEventListener('change',e=>showSwap(index,kind,e.target.value));document.querySelector('#swap-more')?.addEventListener('click',()=>showSwap(index,kind,order,limit+6));
}
function chooseDay(id){
 if(!state.ids.some(Boolean)){showFirstDish(id);return;}
 const r=dish(id),used=weekEntries(state.ids,state.profile,state.courses).find(e=>e.id===id);
 openModal(`<div class="cook-view"><div class="eyebrow">${r.name}</div><h2>Pour quel <em>moment?</em></h2>${used?`<p class="info-strip">Déjà prévu ${days[used.index].toLowerCase()}. Une recette ne peut figurer qu’une fois dans la semaine.</p>`:''}<div class="choices">${activeDays(state.profile).map(i=>{const available=(!used||used.index===i)&&eligibleRecipes(state.profile,i,r.course,{manual:true}).some(x=>x.id===id)&&(r.course==='main'||state.profile.events[i]?.[r.course]);return `<button class="choice" ${available?'':'disabled'} data-replace="${id}" data-index="${i}" data-replace-kind="${r.course}"><strong>${days[i]}</strong><small>${r.course==='main'?(dish(state.ids[i])?.name||'Plat à composer'):state.profile.events[i]?eventLabels[state.profile.events[i].theme]:'Ajoutez une occasion avec cette inclusion'}</small></button>`;}).join('')}</div><p class="fine mt">Les entrées et desserts s’ajoutent aux journées comportant une occasion et l’inclusion correspondante.</p></div>`);
}

function info(){openModal(`<div class="cook-view"><div class="eyebrow">La version découverte</div><h2>Ce que vous pouvez<br><em>déjà faire.</em></h2><p>Composer un menu à partir de 31 recettes illustrées, ajuster les portions, remplacer les plats, garder vos favoris, consulter les étapes détaillées et exporter votre liste.</p><p class="fine">La recherche par envie et le renouvellement proposent les recettes de la collection. Sans service configuré, les choix sont calculés localement : aucune nouvelle recette n’est générée par IA. Le client de connexion au futur service IA et aux prix automatiques est préparé; les services ne sont pas encore branchés. Les commandes écrites sont limitées aux exemples indiqués. Les équivalences physiques sont des repères approximatifs : gardez les grammes comme référence. Vos préférences sont enregistrées sur cet appareil; aucun compte ni abonnement n’est créé.</p><p class="fine">Les photos sont de vraies photographies Pexels utilisées sous licence. Les plats ont été rapprochés de leur photographie. Les recettes sans photo fidèle restent hors de la collection. Les variantes lunch n’ont pas encore leur propre photographie. Les sources et licences sont documentées dans les crédits fournis avec le projet.</p><p class="fine">Nom de travail Sauge. Prix d’épicerie indicatifs. Les allergènes et la salubrité doivent être vérifiés avant de cuisiner.</p><button class="primary" data-close>Continuer la découverte ${icon('arrow')}</button></div>`);}
function rememberDraft(){if(draft){try{localStorage.setItem(communityUI.localKey()+'-draft',JSON.stringify({draft,step}));}catch{}}}
function bindFolds(root){root.querySelectorAll('[data-fold]').forEach(el=>el.addEventListener('toggle',()=>{if(el.isConnected){if(el.open)detailsOpen.add(el.dataset.fold);else detailsOpen.delete(el.dataset.fold);}}));}
function showPrep(){
 const entries=weekEntries(state.ids,state.profile,state.courses),unique=[...new Set(entries.map(e=>e.id))];
 const lunchCount=activeDays(state.profile).reduce((n,i)=>n+lunchForDay(state.profile,i),0);
 openModal(`<div class="cook-view prep-view"><div class="eyebrow">Pour votre menu actuel</div><h2>Tout préparer.<br><em>Sans rien deviner.</em></h2><p class="fine">Quantités complètes à préparer pour chaque repas, lunchs et taille des portions compris. Le stock n’est pas déduit ici : il est déduit de votre liste d’épicerie. Cette liste suit votre menu actuel.</p><div class="prep-checklist">${unique.map(id=>{const r=dish(id),entry=entries.find(e=>e.id===id),ids=Array(dayCount(state.profile)).fill(null),courses={};if(entry.course==='main')ids[entry.index]=id;else courses[entry.index]={[entry.course]:id};const amounts=consolidateWeek(ids,state.profile,{},courses),variant=entry.course==='main'?lunchVariant(r,state.profile):null;return `<article class="prep-task prep-recipe ${state.prepChecks[id]?'complete':''}"><div><label class="prep-task-heading"><input type="checkbox" data-prep="${id}" ${state.prepChecks[id]?'checked':''}><strong>${esc(r.name)}</strong></label><p class="fine">${days[entry.index]} · ${entry.portions} portions équivalentes${entry.course==='main'?' · '+supperPeople(state.profile,entry.index)+' à table + '+lunchForDay(state.profile,entry.index)+' lunch':' · pour les convives'}</p><h3>À préparer avant de commencer</h3><p class="prep-instructions">${cookingText(r.prepAhead)}</p><h3>Les quantités pour ce repas</h3><ul class="prep-amounts">${amounts.map(row=>`<li><span>${esc(row.name)}</span><strong>${quantityLabel(row.id,row.total)}</strong></li>`).join('')}</ul>${variant?`<p class="fine">La variante lunch « ${esc(variant.name||variant.title||'Lunch transformé')} » est incluse dans ces quantités. Réserver ses ingrédients avant de cuisiner. ${cookingText(variant.steps)}</p>`:''}<p class="fine">Sel, poivre et eau selon les étapes et votre goût. Les repères physiques sont approximatifs; le poids ou volume affiché fait référence.</p><details class="prep-full-steps"><summary>Voir toutes les étapes · ${r.time} min</summary><ol>${r.steps.map(t=>`<li>${cookingText(t)}</li>`).join('')}</ol></details><button class="text-link" data-recipe="${id}" data-recipe-day="${entry.index}">Voir la recette complète →</button></div></article>`;}).join('')}</div>${lunchCount?`<div class="review"><strong>${lunchCount} portions lunch sont prévues dans la semaine.</strong><br>Préparez les contenants propres et identifiez la date de préparation. Réservez les quantités avant de servir le souper.</div>`:''}<div class="info-strip">Cette liste concerne la mise en place, pas la conservation de tous les repas cuits pour cinq jours. Gardez les aliments crus séparés et au froid; suivez les conseils de conservation de chaque recette.</div><button class="secondary" data-close>C’est noté ${icon('check')}</button></div>`);
}
function finishQuiz(){
 if(!captureStore('quiz'))return;
 draft.profile=normalizeProfile(draft.profile);
 const result=generatePlan(draft.profile,draft.pantry,state.rotation,{priority:draft.priority||[],offerPrices:currentOfferPrices()});
 if(result.error){pendingPartial={result,profile:structuredClone(draft.profile),pantry:structuredClone(draft.pantry)};document.querySelector('#quiz-error').innerHTML=diagnosticHtml(result);bindDiagnostics();return;}
 state.profile=structuredClone(draft.profile);state.baseProfile=normalizeProfile({...draft.profile,events:{}});state.pantry=structuredClone(draft.pantry);state.pantryPriority=(draft.priority||[]).slice();state.ids=result.ids;state.courses=result.courses||{};state.onboarded=true;state.checked={};state.locked={};state.prepChecks={};selectedDay=0;
 try{localStorage.removeItem(communityUI.localKey()+'-draft');}catch{}
 draft=null;save();go('menu');toast('Votre semaine est prête. Bon appétit!');
}
function adjust(text){
 const t=text.trim().toLowerCase();let p=structuredClone(state.profile);
 if(/végétarien|vegetarien/.test(t)){p.diet='vegetarian';p.veg=true;}
 else if(/plus rapide|rapide/.test(t))p.maxTime=25;
 else if(/moins cher|budget/.test(t))p.goal='budget';
 else if(/sans poulet/.test(t))p.excluded=[...new Set([...p.excluded,'chicken'])];
 else{chatAnswer='Essayez « végétarien », « plus rapide », « moins cher » ou « sans poulet ». Cette version ne comprend pas encore les demandes libres.';render();return;}
 p=normalizeProfile(p);
 const result=generatePlan(p,state.pantry,state.rotation,planOptions());
 if(result.error){chatAnswer=result.error;render();return;}
 state.profile=p;state.ids=result.ids;state.courses=result.courses||{};state.checked={};state.prepChecks={};chatAnswer='Votre menu et votre liste ont été recalculés. Les repas conservés restent à leur place.';save();render();
}

function download(){
 const ingredientsText=shopping().filter(r=>r.needed>0).map(r=>(state.checked[r.id]?'[x]':'[ ]')+' '+r.name+' : '+quantityLabel(r.id,r.needed)).join('\n');
 const extraText=state.extraItems.map(r=>(state.checked['extra-'+r.id]?'[x]':'[ ]')+' '+r.name+' '+r.quantity+' — '+(r.estimatedPrice===null?'sans prix':money(r.estimatedPrice))).join('\n');
 const basket=purchaseEstimate(shopping(),liveOffers(),state.store,state.shoppingDate);
 const packText=basket.entries.filter(r=>r.covered).map(r=>r.name+' : '+r.packs+' × '+r.offer.size+' '+r.unit+' = '+money(r.total)+' (surplus '+quantityLabel(r.id,r.surplus)+') — '+r.offer.start+' au '+r.offer.end+' — '+r.offer.source).join('\n');
 const content='SAUGE — MA LISTE D’ÉPICERIE\n\n'+ingredientsText+(extraText?'\n\nAUTRES ACHATS\n'+extraText:'')+'\n\nMenu à acheter : '+money(cost())+'\nAutres achats renseignés : '+money(extraCost())+'\nTotal indicatif : '+money(cost()+extraCost())+'\n'+(state.extraItems.some(r=>r.estimatedPrice===null)?'Total partiel : certains achats n’ont pas de prix.\n':'')+'Quantités utilisées, hors formats d’emballage.\n';
 const annotated=content+'\nMAGASIN : '+(storeDirectory[state.store.id]?.name||'Non choisi')+' — '+state.store.postal+' — '+state.store.branch+'\nÉPICERIE PRÉVUE : '+state.shoppingDate+'\nFORMATS VÉRIFIÉS LORSQUE DISPONIBLES; AUTRES PRIX ESTIMÉS\n'+packText+'\nTotal mixte formats/estimations : '+money(basket.total+extraCost())+'\n';
 const url=URL.createObjectURL(new Blob(['\ufeff'+annotated],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mijote-ma-liste.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Votre liste a été téléchargée.');
}

function bindModal(){
 const root=document.querySelector('#modal-content');
 root.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>showRecipe(b.dataset.recipe,b.hasAttribute('data-recipe-day')?Number(b.dataset.recipeDay):recipeDay));
 root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>chooseDay(b.dataset.add));
 root.querySelectorAll('[data-replace]').forEach(b=>b.onclick=()=>replaceSelection(b.dataset.replace,Number(b.dataset.index),b.dataset.replaceKind||'main'));
 root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.querySelector('#modal').close());
 root.querySelectorAll('[data-prep]').forEach(el=>el.onchange=()=>{state.prepChecks[el.dataset.prep]=el.checked;el.closest('.prep-task').classList.toggle('complete',el.checked);save();});
 root.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{occasionDraft.event.theme=b.dataset.theme;renderOccasion();});
 root.querySelector('#occasion-enabled')?.addEventListener('change',e=>{occasionDraft.enabled=e.target.checked;});
 root.querySelector('#occasion-people')?.addEventListener('change',e=>{occasionDraft.event.people=Math.round(clamp(e.target.value,1,12,2));e.target.value=occasionDraft.event.people;});
 root.querySelector('#occasion-time')?.addEventListener('change',e=>{occasionDraft.event.maxTime=Number(e.target.value);});
 root.querySelector('#occasion-service')?.addEventListener('change',e=>{occasionDraft.event.service=e.target.value||'19:00';});
 root.querySelector('#occasion-starter')?.addEventListener('change',e=>{occasionDraft.event.starter=e.target.checked;});
 root.querySelector('#occasion-dessert')?.addEventListener('change',e=>{occasionDraft.event.dessert=e.target.checked;});
 root.querySelector('#occasion-save')?.addEventListener('click',saveOccasion);
 bindExperience(root);bindDiscovery(root);bindWeekTools(root);bindFolds(root);communityUI.bind(root);bindAtmosphere(root);
}

