 document.querySelectorAll('[data-lock]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.lock);state.locked[i]=!state.locked[i];save();render();toast(state.locked[i]?'Ce repas sera conservé lors de la prochaine proposition.':'Ce repas pourra être remplacé dans la prochaine proposition.');});
