 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const k=b.dataset.choice;draft.profile[k]=k==='maxTime'?Number(b.dataset.value):b.dataset.value;if(k==='goal'&&b.dataset.value==='quick')draft.profile.maxTime=25;updateDraft();});
