 document.querySelectorAll('[data-counter]').forEach(b=>b.onclick=()=>{const k=b.dataset.counter;draft.profile[k]=clamp(draft.profile[k]+Number(b.dataset.delta),k==='people'?1:0,12);updateDraft();});
 const toggleDraft=(key,id)=>{draft.profile[key]=draft.profile[key].includes(id)?draft.profile[key].filter(x=>x!==id):[...draft.profile[key],id];updateDraft();};
 document.querySelectorAll('[data-exclude]').forEach(b=>b.onclick=()=>toggleDraft('excluded',b.dataset.exclude));
 document.querySelectorAll('[data-allergen]').forEach(b=>b.onclick=()=>toggleDraft('allergens',b.dataset.allergen));
 document.querySelectorAll('[data-equipment]').forEach(b=>b.onclick=()=>toggleDraft('equipment',b.dataset.equipment));
