 document.querySelector('#quiz-budget')?.addEventListener('change',e=>{draft.profile.budget=clamp(e.target.value,1,3000,120);e.target.value=draft.profile.budget;rememberDraft();});
 document.querySelectorAll('[data-quiz-stock]').forEach(el=>el.onchange=()=>{draft.pantry[el.dataset.quizStock]=clamp(el.value,0,100000);el.value=draft.pantry[el.dataset.quizStock];rememberDraft();});
 document.querySelector('#quiz-later')?.addEventListener('click',skipOptionalQuiz);document.querySelector('#quiz-save-exit')?.addEventListener('click',()=>{rememberDraft();go('explore');toast('Vos réponses sont gardées. Reprenez le parcours depuis Mon compte.');});document.querySelectorAll('[data-resume-quiz]').forEach(b=>b.onclick=startQuiz);
 document.querySelector('#quiz-back')?.addEventListener('click',()=>{if(step){step--;render();}else go('home');});
