 document.querySelectorAll('[data-check]').forEach(el=>el.onchange=()=>{state.checked[el.dataset.check]=el.checked;save();render();});
 document.querySelectorAll('[data-stock]').forEach(el=>el.onchange=()=>{state.pantry[el.dataset.stock]=clamp(el.value,0,100000);el.value=state.pantry[el.dataset.stock];state.checked={};save();document.querySelector('#stock-count').textContent=Object.values(state.pantry).filter(n=>n>0).length+' ingrédients';toast('Inventaire enregistré. Liste d’épicerie recalculée.');});
 document.querySelectorAll('[data-priority]').forEach(b=>b.onclick=()=>{const id=b.dataset.priority;state.pantryPriority=state.pantryPriority.includes(id)?state.pantryPriority.filter(x=>x!==id):[...state.pantryPriority,id];save();render();toast('Priorité enregistrée pour la prochaine proposition de menu.');});
 document.querySelector('#extra-form')?.addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#extra-name').value.trim();if(!name)return;if(state.extraItems.length>=100){toast('La liste contient déjà 100 achats supplémentaires.');return;}const quantity=document.querySelector('#extra-quantity').value.trim();const price=document.querySelector('#extra-price').value;state.extraItems.push({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),name:name.slice(0,60),quantity:quantity.slice(0,30),estimatedPrice:price===''?null:clamp(price,0,10000)});save();render();toast('Article ajouté à votre liste.');});
 document.querySelectorAll('[data-remove-extra]').forEach(b=>b.onclick=()=>{const id=b.dataset.removeExtra;state.extraItems=state.extraItems.filter(r=>r.id!==id);delete state.checked['extra-'+id];save();render();});
