 document.querySelectorAll('[data-quiz-day]').forEach(el=>el.onchange=()=>{const i=Number(el.dataset.quizDay);draft.profile.activeDays=el.checked?[...new Set([...draft.profile.activeDays,i])]:draft.profile.activeDays.filter(n=>n!==i);updateDraft();});
 document.querySelector('[data-quiz-weekend]')?.addEventListener('change',e=>{draft.profile.weekend=e.target.checked;draft.profile.activeDays=e.target.checked?[...new Set([...draft.profile.activeDays,5,6])]:draft.profile.activeDays.filter(n=>n<5);updateDraft();});
