 document.querySelector('#more-recipes')?.addEventListener('click',()=>{desireSeen=[];visibleRecipes+=12;render();});
 document.querySelectorAll('[data-event-preset]').forEach(b=>b.onclick=()=>{if(!hasPlus()){showPlusFeature('occasion');return;}const theme=b.dataset.eventPreset,index=theme==='brunch'?6:5;if(state.ids.length){showOccasion(index);occasionDraft.event.theme=theme;renderOccasion();}else{startQuiz();draft.profile.weekend=true;draft.profile.activeDays=[0,1,2,3,4,5,6];draft.profile.events[index]={theme,starter:true,dessert:true,people:theme==='romantic'?2:draft.profile.people,maxTime:60};render();}});
 document.querySelector('#exclude-search')?.addEventListener('input',e=>{const key=e.target.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();document.querySelectorAll('[data-exclude]').forEach(b=>{b.hidden=!b.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(key);});});
