const weekFlow=createWeekFlow({esc,photo,money,openModal,getState:()=>state,toast,commit:(profile,result)=>{if(state.ids.some(Boolean))archiveWeek();state.profile=profile;state.ids=result.ids;state.courses=result.courses||{};state.rotation++;state.checked={};state.locked={};state.prepChecks={};state.extraItems=[];state.timer=null;state.onboarded=true;selectedDay=activeDays(profile)[0]||0;save();go('menu');toast('Votre semaine est validée. Les quantités et l’épicerie sont prêtes.');}});
const communityUI=createCommunityExperience({esc,openModal,go,render,toast,getState:()=>state,setState:value=>{state=value;},cleanBackup,persistLocal,save,showPreferences,showRecipe,chooseDay,resumeQuiz:startQuiz});
document.querySelector('.modal-close').onclick=()=>document.querySelector('#modal').close();
document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['home','quiz','explore','favorites','menu','list','pantry','plans','market','journal','personal','admin'].includes(next)){page=next;render();window.scrollTo(0,0);}});
