page=['home','quiz','explore','favorites','menu','list','pantry','plans','market','journal','personal','admin'].includes(location.hash.slice(1))?location.hash.slice(1):'home';
if(location.hash==='#quiz'&&restoreDraft())page='quiz';
if(state.ids.length&&(new Set(state.ids.filter(Boolean)).size!==state.ids.filter(Boolean).length||weekEntries(state.ids,state.profile,state.courses).some(e=>!eligibleRecipes(state.profile,e.index,e.course).some(r=>r.id===e.id)))){const fresh=generatePlan(state.profile,state.pantry,state.rotation,{priority:state.pantryPriority});state.ids=fresh.error?(fresh.partial?.ids||[]):fresh.ids;state.courses=fresh.error?(fresh.partial?.courses||{}):(fresh.courses||{});state.locked={};state.checked={};save();}
history.replaceState(null,'','#'+page);
render();
function storeFields(store,prefix='market'){
 return `<section class="store-box"><div class="eyebrow">Votre épicerie, votre quartier</div><label for="${prefix}-store">Où faites-vous l’épicerie?</label><select id="${prefix}-store">${[['','Choisir mon épicerie'],...Object.entries(storeDirectory).map(([id,s])=>[id,s.name])].map(([id,label])=>`<option value="${id}" ${store.id===id?'selected':''}>${label}</option>`).join('')}</select><div class="store-address"><label>Code postal québécois<input id="${prefix}-postal" maxlength="7" placeholder="H2X 1Y4" value="${esc(store.postal)}" autocomplete="postal-code"></label><label>Succursale / quartier<input id="${prefix}-branch" maxlength="100" placeholder="Ex. : rue Jean-Talon, Montréal" value="${esc(store.branch)}"></label></div><p class="fine">Le magasin et la succursale déterminent les offres à vérifier. Pas de localisation automatique. Vous pouvez compléter ces choix plus tard.</p>${prefix==='market'?`<label>Date prévue pour l’épicerie<input id="shopping-date" type="date" min="${localDate()}" value="${state.shoppingDate}"></label>`:''}${prefix==='market'?'<button class="primary" id="store-save">Enregistrer mon épicerie</button>':''}<p id="store-feedback" class="fine" role="status"></p></section>`;
}
function captureStore(prefix){
 const input=document.querySelector('#'+prefix+'-store');if(!input)return true;
 const store=normalizeStore({id:input.value,postal:document.querySelector('#'+prefix+'-postal').value,branch:document.querySelector('#'+prefix+'-branch').value});
 if(store.postal&&!validPostal(store.postal)){toast('Vérifiez le code postal québécois, par exemple H2X 1Y4.');return false;}
 const date=document.querySelector('#shopping-date')?.value;if(date&&(!validDate(date)||date<localDate())){toast('Choisissez une date d’épicerie valide, à partir d’aujourd’hui.');return false;}if(date)state.shoppingDate=date;
 const changed=JSON.stringify(store)!==JSON.stringify(state.store);state.store=store;if(changed)state.checked={};save();return true;
}
function storeInline(){const store=storeDirectory[state.store.id];return `<div class="store-inline"><span>${icon('bag')} ${store?'Mon épicerie : <strong>'+store.name+'</strong>':'Votre épicerie accompagne vos envies'}${state.store.branch?' · '+esc(state.store.branch):''}</span><button class="text-link" data-store-settings>${store?'Modifier':'Choisir mon épicerie'} →</button><small>${feedLabel()}</small></div>`;}
function basketPanel(){
 const estimate=purchaseEstimate(shopping(),liveOffers(),state.store,state.shoppingDate);
 return `<section class="automatic-basket">${storeInline()}${estimate.covered?`<div class="automatic-price"><strong>${money(estimate.total+extraCost())}</strong><span>${estimate.covered} / ${estimate.entries.length} ingrédients aux formats vérifiés pour le ${state.shoppingDate}. Les autres prix restent estimés.</span></div><p class="fine">Écart sur les articles avec prix de référence : ${money(estimate.savings)}. Sources et formats disponibles dans le détail des prix.</p><button class="text-link" id="price-details">Voir le détail des prix →</button>`:'<p class="fine">Votre liste se prépare avec vos recettes et votre inventaire. Aucune circulaire à recopier.</p>'}</section>`;
}
// Old links open the shopping list; there is no separate flyer workflow.
function market(){return list();}

function pantrySummary(){
 const rows=consolidateWeek(state.ids,state.profile,{},state.courses),balance=pantryBalance(rows,state.pantry),today=localDate();
 return `<section class="pantry-overview"><h3>Après le menu, il restera…</h3>${balance.filter(r=>r.left>0).map(r=>`<p><strong>${ingredients[r.id][0]}</strong> ${quantityLabel(r.id,r.left)}</p>`).join('')||'<p class="fine">Renseignez votre stock pour prévoir les surplus.</p>'}<div class="expiry-alerts">${balance.filter(r=>state.expiry[r.id]&&state.expiry[r.id]<=today).map(r=>`<p class="warning">${ingredients[r.id][0]} : date à vérifier (${esc(state.expiry[r.id])}). Contrôlez le produit avant utilisation; cette date ne prouve pas sa salubrité.</p>`).join('')}</div><p class="fine">Les dates sont vos repères, sans diagnostic de salubrité. Les stocks ne sont retirés qu’après confirmation explicite.</p><button class="secondary" id="consume-pantry" ${state.ids.some(Boolean)?'':'disabled'}>J’ai cuisiné toute cette semaine : mettre le stock à jour</button></section>`;
}
function planGaps(){
 const gaps=activeDays(state.profile).flatMap(i=>[...(!state.ids[i]?[days[i]+' : plat']:[]),...['starter','dessert'].filter(k=>state.profile.events[i]?.[k]&&!state.courses[i]?.[k]).map(k=>days[i]+' : '+(k==='starter'?'entrée':'dessert'))]);
 return gaps.length?`<div class="info-strip warning"><strong>Menu incomplet — ${gaps.length} recette${gaps.length>1?'s':''} à choisir.</strong><p>${gaps.join(' · ')}</p><p>La liste contient seulement les recettes choisies. Les portions annoncées pour les journées incomplètes ne sont pas toutes couvertes.</p><button class="text-link" data-start>Revoir mes choix →</button></div>`:'';
}
function diagnosticHtml(result){
 return `<div class="info-strip warning"><strong>Il reste des repas à composer.</strong><p>${esc(result.error)}</p>${(result.shortages||[]).map(x=>`<p>${days[x.index]} · ${x.course==='main'?'plat':x.course==='starter'?'entrée':'dessert'} : ${x.compatible} recette${x.compatible>1?'s':''} compatible${x.compatible>1?'s':''}. ${esc(x.reason)}</p>`).join('')}<p>Essayez un autre thème ou plus de temps. Aucun filtre alimentaire ne sera retiré automatiquement.</p></div>${result.partial&&result.matched?`<button class="secondary" id="accept-partial">Garder les ${result.matched} recettes possibles et compléter ensuite</button>`:''}<button class="text-link" id="review-constraints">Revoir mes contraintes →</button>`;
}
function bindDiagnostics(){document.querySelector('#review-constraints')?.addEventListener('click',()=>{startQuiz();step=2;detailsOpen.add('food-constraints');render();});document.querySelector('#accept-partial')?.addEventListener('click',()=>{if(!pendingPartial)return;const {result,profile,pantry,baseProfile}=pendingPartial;state.profile=profile;if(baseProfile)state.baseProfile=baseProfile;state.pantry=pantry;state.ids=result.partial.ids;state.courses=result.partial.courses;state.onboarded=true;state.locked={};state.checked={};state.prepChecks={};draft=null;try{localStorage.removeItem(communityUI.localKey()+'-draft');}catch{}pendingPartial=null;save();go('menu');toast('Les recettes disponibles sont conservées. Le menu reste signalé incomplet.');});}
function recipeNotebook(r){const n=state.notes[r.id]||{};return `${communityUI.ratingPanel(r)}<section class="recipe-notebook"><h3>Mon carnet de cuisine</h3>${n.rating?`<p class="fine">Ancienne appréciation privée : ${Number(n.rating)} / 5.</p>`:""}<label>Mes notes<textarea data-note="${r.id}" maxlength="1000" placeholder="Un peu plus de citron la prochaine fois…">${esc(n.text||'')}</textarea></label><p class="fine">Notes privées${communityUI.user()?' sauvegardées avec votre compte':' sur cet appareil'}.</p></section>`;}
function updateTimer(){
 let badge=document.querySelector('#timer-badge');if(!badge&&document.createElement){badge=document.createElement('div');badge.id='timer-badge';badge.className='timer-badge';badge.setAttribute('role','status');document.body.appendChild(badge);}if(!badge)return;
 if(!state.timer){badge.hidden=true;return;}badge.hidden=false;const seconds=Math.max(0,Math.ceil((state.timer.endsAt-Date.now())/1000));badge.innerHTML=`<span>${seconds?Math.floor(seconds/60)+' min '+String(seconds%60).padStart(2,'0')+' s':'Minuterie terminée'} · ${esc(state.timer.title)}</span><button id="timer-stop" aria-label="Fermer la minuterie">×</button>`;badge.querySelector('#timer-stop').onclick=()=>{state.timer=null;save();updateTimer();};
}
function showTimeline(index){
 const e=state.profile.events[index];if(!e)return;
 const entries=weekEntries(state.ids,state.profile,state.courses).filter(r=>r.index===index),timeline=occasionTimeline(entries,recipes,e.service||'19:00');
 openModal(`<div class="cook-view"><div class="eyebrow">${eventLabels[e.theme]} · ${e.people} personnes</div><h2>Tout préparer.<br><em>Puis en profiter.</em></h2><p>À table vers ${esc(e.service||'19:00')}. Voici une base prudente de préparation, avec une seule recette à la fois et dix minutes entre les recettes.</p><div class="timeline">${timeline.map(t=>`<article><time>${t.label}</time><div><h3>${t.recipe.name}</h3><p>${t.recipe.time} min · ${t.equipment.map(x=>equipmentLabels[x]).join(' · ')}</p><p class="fine">Avant : ${t.recipe.prepAhead}</p><button class="text-link" data-recipe="${t.id}" data-recipe-day="${index}">Voir les étapes →</button></div></article>`).join('')}</div><div class="info-strip">Ce déroulé séquentiel évite de réserver le même appareil à deux recettes en même temps. Les temps restent indicatifs : prévoyez une marge. Réfrigérez rapidement les préparations faites d’avance, puis réchauffez au besoin selon leur recette. Ne les laissez pas attendre à température ambiante.</div><button class="secondary" data-menu-card="${index}">Voir mon menu à partager</button></div>`);
}
function menuCard(index){const e=state.profile.events[index];if(!e)return;openModal(`<div class="menu-card"><div class="brand">sauge.</div><div class="eyebrow">${eventLabels[e.theme]}</div><h2>Le plaisir<br><em>d’être ensemble.</em></h2><p>${days[index]} · ${e.people} convives · ${esc(e.service||'19:00')}</p>${weekEntries(state.ids,state.profile,state.courses).filter(x=>x.index===index).sort((a,b)=>({starter:0,main:1,dessert:2}[a.course]-{starter:0,main:1,dessert:2}[b.course])).map(x=>`<div><small>${{starter:'POUR COMMENCER',main:'LE PLAT',dessert:'LA TOUCHE SUCRÉE'}[x.course]}</small><h3>${dish(x.id).name}</h3></div>`).join('')}<button class="primary" data-export-menu="${index}">Télécharger le menu à partager ↓</button></div>`);}
function textDownload(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function archiveWeek(){if(!state.ids.some(Boolean)){toast('Composez d’abord un menu.');return;}state.history.unshift({id:Date.now().toString(36),date:localDate(),profile:structuredClone(state.profile),ids:state.ids.slice(),courses:structuredClone(state.courses)});state.history=state.history.slice(0,20);save();toast('Semaine enregistrée. Retrouvez-la dans « Mes semaines ».');}
function restoreWeek(id){const h=state.history.find(h=>h.id===id);if(!h)return;const p=normalizeProfile(h.profile),ids=Array.from({length:dayCount(p)},(_,i)=>activeDays(p).includes(i)&&eligibleRecipes(p,i,'main',{manual:true}).some(r=>r.id===h.ids[i])?h.ids[i]:null),courses={};for(const i of activeDays(p))for(const k of ['starter','dessert'])if(p.events[i]?.[k]&&eligibleRecipes(p,i,k,{manual:true}).some(r=>r.id===h.courses?.[i]?.[k])){courses[i]??={};courses[i][k]=h.courses[i][k];}const entries=weekEntries(ids,p,courses);if(new Set(entries.map(x=>x.id)).size!==entries.length){toast('Cette sauvegarde contient des doublons et ne peut être restaurée.');return;}state.profile=p;state.ids=ids;state.courses=courses;state.locked={};state.checked={};state.prepChecks={};state.onboarded=true;save();go('menu');toast('Semaine restaurée. Vérifiez vos stocks et les offres actuelles.');}
function journal(){return `<div class="wrap"><div class="account-save-note">Brouillon enregistré sur cet appareil. <button class="text-link" data-account>Un compte pour retrouver mes données partout →</button></div>${title('Vos semaines et vos données','Les bonnes idées.<br><em>À retrouver.</em>','Conservez vos menus préférés et une sauvegarde privée de vos choix.')}<div class="journal-tools"><button class="primary" id="archive-week">Enregistrer ma semaine actuelle</button><button class="secondary" id="backup-export">Exporter ma sauvegarde</button><label class="secondary file-label">Importer ma sauvegarde<input type="file" id="backup-import" accept="application/json,.json"></label></div><p class="fine">Les données restent sur cet appareil. La sauvegarde contient vos préférences, vos notes et votre inventaire. Aucun compte partagé n’est encore connecté. Importer remplace les données actuelles après votre confirmation.</p><div class="history-grid">${state.history.map(h=>`<article class="panel"><div class="eyebrow">${esc(h.date)}</div><h3>${h.ids.filter(Boolean).length} soupers à retrouver</h3><p class="fine">${h.ids.filter(id=>dish(id)).map(id=>esc(dish(id).name)).join(' · ')}</p><button class="primary" data-restore-week="${esc(h.id)}">Reprendre ce menu</button><button class="text-link" data-delete-week="${esc(h.id)}">Retirer</button></article>`).join('')||'<p class="fine">Vos semaines enregistrées apparaîtront ici.</p>'}</div></div>`;}
function liveOffers(){const age=Date.now()-Date.parse(offerFeed.verifiedAt);if(offerFeed.status!=='ready'||!Number.isFinite(age)||age< -300000||age>86400000)return [];return automaticOffers.filter(o=>o.verified&&o.origin==='partner'&&offerStatus(o,state.store,state.shoppingDate)==='active');}
function currentOfferPrices(){const prices={};for(const o of liveOffers())prices[o.ingredient]=Math.min(prices[o.ingredient]??Infinity,o.price/o.size);return prices;}

function bindExperience(root=document){
 root.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>showMove(Number(b.dataset.move)));
 root.querySelectorAll('[data-move-target]').forEach(b=>b.onclick=()=>moveMeal(Number(b.dataset.from),Number(b.dataset.moveTarget)));

 root.querySelector('#store-save')?.addEventListener('click',()=>{if(captureStore('market')){document.querySelector('#modal').close();automaticOffers=[];offerFeed={status:'unavailable',key:'',provider:'',verifiedAt:null};render();toast('Votre épicerie est enregistrée.');}});
 for(const suffix of ['store','postal','branch'])root.querySelector('#quiz-'+suffix)?.addEventListener('change',()=>captureStore('quiz'));
 root.querySelectorAll('[data-timeline]').forEach(b=>b.onclick=()=>showTimeline(Number(b.dataset.timeline)));
 root.querySelectorAll('[data-menu-card]').forEach(b=>b.onclick=()=>menuCard(Number(b.dataset.menuCard)));
 root.querySelectorAll('[data-export-menu]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.exportMenu),e=state.profile.events[i];textDownload('mijote-mon-menu.txt','SAUGE — '+eventLabels[e.theme]+'\n'+e.people+' convives · '+(e.service||'19:00')+'\n\n'+weekEntries(state.ids,state.profile,state.courses).filter(x=>x.index===i).sort((a,b)=>({starter:0,main:1,dessert:2}[a.course]-{starter:0,main:1,dessert:2}[b.course])).map(x=>({starter:'Entrée',main:'Plat',dessert:'Dessert'}[x.course])+ ' : '+dish(x.id).name).join('\n'));});
 root.querySelector('#recipe-scale')?.addEventListener('change',e=>showRecipe(e.target.dataset.id,recipeDay,Math.round(clamp(e.target.value,1,36,2))*Number(e.target.dataset.factor||1)));
 root.querySelectorAll('[data-note]').forEach(el=>el.onchange=()=>{state.notes[el.dataset.note]??={};state.notes[el.dataset.note].text=el.value.slice(0,1000);save();});
 root.querySelectorAll('[data-rating]').forEach(el=>el.onchange=()=>{state.notes[el.dataset.rating]??={};state.notes[el.dataset.rating].rating=clamp(el.value,0,5);save();});
 root.querySelectorAll('[data-expiry]').forEach(el=>el.onchange=()=>{state.expiry[el.dataset.expiry]=el.value;save();});
 root.querySelector('#consume-pantry')?.addEventListener('click',()=>{openModal(`<div class="cook-view"><h2>Mettre le stock <em>à jour?</em></h2><p>À confirmer seulement après avoir cuisiné tous les repas actuellement prévus. Les quantités utilisées seront retirées une fois de votre inventaire. Si vous n’avez cuisiné qu’une partie, ajustez les quantités à la main.</p><button class="primary" id="consume-confirm">Oui, j’ai tout cuisiné</button><button class="secondary" data-close>Annuler</button></div>`);document.querySelector('#consume-confirm').onclick=()=>{const signature=JSON.stringify({ids:state.ids,courses:state.courses,profile:state.profile});if(signature===state.consumedSignature){toast('Le stock a déjà été ajusté pour ce menu.');return;}const rows=consolidateWeek(state.ids,state.profile,{},state.courses);for(const r of rows)state.pantry[r.id]=Math.max(0,(state.pantry[r.id]||0)-r.total);state.consumedSignature=signature;state.checked={};save();go('pantry');toast('Inventaire ajusté.');};});
 root.querySelector('#archive-week')?.addEventListener('click',archiveWeek);
 root.querySelectorAll('[data-restore-week]').forEach(b=>b.onclick=()=>restoreWeek(b.dataset.restoreWeek));
 root.querySelectorAll('[data-delete-week]').forEach(b=>b.onclick=()=>{state.history=state.history.filter(h=>h.id!==b.dataset.deleteWeek);save();render();});
 root.querySelector('#backup-export')?.addEventListener('click',()=>textDownload('mijote-sauvegarde.json',JSON.stringify({schema:'mijote-backup-v1',state},null,2),'application/json'));
 root.querySelector('#backup-import')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>2000000){toast('Sauvegarde trop volumineuse (2 Mo maximum).');return;}try{const raw=JSON.parse((await file.text()).replace(/^\uFEFF/,''));if(raw.schema!=='mijote-backup-v1'||!raw.state||!Array.isArray(raw.state.ids))throw Error();const clean=cleanBackup(raw.state);openModal('<div class="cook-view"><h2>Restaurer cette <em>sauvegarde?</em></h2><p>Elle remplacera vos préférences, votre menu, votre inventaire, vos offres et vos notes sur cet appareil. Exportez votre sauvegarde actuelle si vous voulez la garder.</p><button class="primary" id="backup-confirm">Remplacer mes données</button><button class="secondary" data-close>Annuler</button></div>');document.querySelector('#backup-confirm').onclick=()=>{state=clean;draft=null;try{localStorage.removeItem(communityUI.localKey()+'-draft');}catch{}save();go('menu');toast('Sauvegarde restaurée. Vérifiez les stocks, les dates et les offres.');};}catch{toast('Fichier de sauvegarde invalide. Vos données sont conservées.');}});
}
function cleanBackup(raw){
 const profile=normalizeProfile(raw.profile||{}),clean={...structuredClone(DEFAULT),profile,baseProfile:normalizeProfile({...raw.baseProfile||profile,events:{}}),shoppingDate:validDate(raw.shoppingDate)&&raw.shoppingDate>=localDate()?raw.shoppingDate:localDate(),store:normalizeStore(raw.store),offers:[],history:[],notes:{},expiry:{},timer:null};
 clean.ids=Array.from({length:dayCount(profile)},(_,i)=>activeDays(profile).includes(i)&&eligibleRecipes(profile,i,'main',{manual:true}).some(r=>r.id===raw.ids?.[i])?raw.ids?.[i]:null);
 clean.courses={};for(const i of activeDays(profile))for(const k of ['starter','dessert'])if(profile.events[i]?.[k]&&eligibleRecipes(profile,i,k,{manual:true}).some(r=>r.id===raw.courses?.[i]?.[k])){clean.courses[i]??={};clean.courses[i][k]=raw.courses[i][k];}
 const used=new Set();for(const entry of weekEntries(clean.ids,profile,clean.courses)){if(used.has(entry.id)){if(entry.course==='main')clean.ids[entry.index]=null;else delete clean.courses[entry.index][entry.course];}else used.add(entry.id);}
 clean.pantry=Object.fromEntries(Object.keys(ingredients).filter(id=>Number(raw.pantry?.[id])>0).map(id=>[id,clamp(raw.pantry[id],0,100000)]));
 clean.favorites=(Array.isArray(raw.favorites)?raw.favorites:[]).filter(id=>dish(id));clean.pantryPriority=(Array.isArray(raw.pantryPriority)?raw.pantryPriority:[]).filter(id=>Object.hasOwn(ingredients,id));
 clean.deferred=(Array.isArray(raw.deferred)?raw.deferred:[]).filter(k=>['pantry','store','preferences'].includes(k));clean.offers=(Array.isArray(raw.offers)?raw.offers:[]).map(o=>normalizeOffer(o,Object.keys(ingredients))).filter(Boolean).slice(0,200);
 clean.extraItems=(Array.isArray(raw.extraItems)?raw.extraItems:[]).filter(r=>r&&typeof r.name==='string').slice(0,100).map((r,i)=>({id:'import-'+i,name:r.name.slice(0,60),quantity:String(r.quantity||'').slice(0,30),estimatedPrice:r.estimatedPrice==null?null:clamp(r.estimatedPrice,0,10000)}));
 clean.notes=Object.fromEntries(recipes.filter(r=>raw.notes?.[r.id]).map(r=>[r.id,{text:String(raw.notes[r.id].text||'').slice(0,1000),rating:clamp(raw.notes[r.id].rating,0,5)}]));
 clean.expiry=Object.fromEntries(Object.keys(ingredients).filter(id=>/^\d{4}-\d{2}-\d{2}$/.test(raw.expiry?.[id]||'')).map(id=>[id,raw.expiry[id]]));
 clean.history=(Array.isArray(raw.history)?raw.history:[]).filter(h=>h&&Array.isArray(h.ids)).slice(0,20).map((h,i)=>({id:'restored-'+i,date:String(h.date||'').slice(0,10),profile:normalizeProfile(h.profile),ids:h.ids.slice(0,7).map(id=>dish(id)?id:null),courses:h.courses&&typeof h.courses==='object'?h.courses:{}}));clean.onboarded=true;return clean;
}
function lunchPanel(r,index){const variant=lunchVariant(r,state.profile),n=lunchForDay(state.profile,index),factor=state.profile.portionSize==='generous'?1.25:state.profile.portionSize==='small'?.75:1;return `<section class="lunch-panel"><div class="eyebrow">Le lunch de demain · ${n} portion${n>1?'s':''}</div><h3>${variant?variant.name:'Réserver avant de servir.'}</h3><p>${variant?variant.steps:r.lunchTip}</p>${variant?`<details><summary>Les quantités réservées pour ces lunchs</summary>${Object.entries(variant.items).map(([id,q])=>`<div class="ingredient-line"><span>${ingredients[id][0]}</span><span>${quantityLabel(id,q*n*factor)}</span></div>`).join('')}</details><p class="fine">Ces quantités sont déjà incluses dans la liste. Les ingrédients cuits communs sont préparés avec le souper, les crudités et tortillas à part. Variante sans photographie dédiée pour le moment.</p>`:`<p class="fine">${state.profile.lunchStyle==='transform'?'Aucune transformation compatible n’est encore disponible pour ce plat : le même repas est réservé. ':''}${r.reheat}</p>`}<p class="fine">Garder au froid, réfrigérer rapidement et suivre les conseils de conservation de la recette.</p></section>`;}

