 const result=generatePlan(profile,state.pantry,state.rotation,r.course==='main'?{locked:{[index]:id},offerPrices:currentOfferPrices()}:{fixedCourses:{[index]:{[r.course]:id}},offerPrices:currentOfferPrices()});
 if(result.error)return result.error;
 state.profile=profile;state.baseProfile=normalizeProfile({...state.baseProfile,people:profile.people,lunch:profile.lunch,allergens:profile.allergens,equipment:profile.equipment,diet:profile.diet,portionSize:profile.portionSize,events:{}});state.ids=result.ids;state.courses=result.courses||{};state.onboarded=true;state.checked={};state.locked={};state.prepChecks={};selectedDay=index;save();go('menu');toast('Votre premier repas est ajouté. Les quantités et l’épicerie sont prêtes.');return null;
