function showNewWeek(){openModal(`<div class="cook-view"><div class="eyebrow">Un nouveau départ, sans tout refaire</div><h2>Une nouvelle<br><em>semaine.</em></h2><p>Vos personnes à table, lunchs habituels, goûts, allergies, équipements, budget et journées de base sont conservés. Votre épicerie, inventaire, favoris et notes restent aussi en place.</p><p>Les plats, soirées thématiques, entrées et desserts d’occasion, cases cochées et achats supplémentaires de cette semaine seront retirés.</p><label class="quick-equipment"><input type="checkbox" id="archive-before-reset" checked> Garder la semaine actuelle dans mon historique sur cet appareil</label><div class="actions"><button class="primary" id="confirm-new-week">Commencer une nouvelle semaine</button><button class="secondary" data-close>Garder ma semaine</button></div></div>`);document.querySelector('#confirm-new-week')?.addEventListener('click',()=>resetWeek(!!document.querySelector('#archive-before-reset')?.checked));}
