function showAccount(){communityUI.openAccount();}
function hasPlus(){return communityUI.user()?.plan==='plus'||communityUI.model.demo&&communityUI.model.previewPlus===true;}
function showPlusFeature(feature='lunch'){openModal(`<div class="cook-view plus-feature"><span class="plus-badge">✦ Sauge Plus</span><h2>Vos soupers sont gratuits.<br><em>Plus va plus loin.</em></h2><p>Chaque variante lunch est une fonction Plus, comme les occasions avec invités, entrées, desserts et heure de service. La planification dédiée des dîners, déjeuners et des ingrédients restants est prévue au lancement.</p><p>Gratuit inclut 7 soupers, leurs recettes détaillées, portions, liste regroupée, inventaire, préférences et portions supplémentaires du même plat pour le lendemain.</p>${communityUI.model.demo?'<button class="primary" id="preview-plus-feature">Essayer Plus dans la démo</button>':'<button class="primary" data-go="plans">Découvrir Sauge Plus</button>'}<button class="text-link" data-close>Continuer avec la version gratuite</button><p class="fine">Aucun paiement ni abonnement n’est activé dans cet aperçu.</p></div>`);document.querySelector('#preview-plus-feature')?.addEventListener('click',()=>{communityUI.model.previewPlus=true;document.querySelector('#modal').close();render();toast('Aperçu Plus activé dans la démo uniquement. Choisissez à nouveau l’option pour l’utiliser.');});}
function skipOptionalQuiz(){if(![0,4].includes(step))return false;if(step===0){step=1;rememberDraft();render();}else{state.deferred=[...new Set([...(state.deferred||[]),'pantry'])];finishQuiz();}return true;}
function showTrialInfo(){openModal(`<div class="cook-view"><div class="eyebrow">Essai proposé pour le lancement</div><h2>Deux semaines.<br><em>Pour prendre goût à Sauge.</em></h2><p>14 jours de Plus, sans carte : le temps de préparer deux vraies semaines. Ensuite, retour à Gratuit si vous ne choisissez pas de vous abonner.</p><p>Vos préférences et vos données restent dans votre compte. Aucun effacement à la fin de l’essai. Un message clair annoncera les fonctions Plus, leur prix et les limites d’IA avant utilisation.</p><p class="fine">Ceci présente le parcours prévu; aucun essai, abonnement ou paiement n’est activé. L’IA, les comptes et les données de rabais doivent fonctionner avant de vendre ces services.</p><button class="primary" data-account>Compte et sauvegarde</button><button class="secondary" data-close>Continuer la découverte</button></div>`);}
function bindWeekTools(root=document){
 root.querySelectorAll('[data-generate-week]').forEach(b=>b.onclick=generateNewWeek);
 root.querySelectorAll('[data-new-week]').forEach(b=>b.onclick=showNewWeek);
 root.querySelectorAll('[data-undo-week]').forEach(b=>b.onclick=undoWeekReset);
 root.querySelectorAll('[data-preferences]').forEach(b=>b.onclick=showPreferences);
 root.querySelectorAll('[data-rescue]').forEach(b=>b.onclick=()=>showRescue(Number(b.dataset.rescue)));
 root.querySelectorAll('[data-rescue-pick]').forEach(b=>b.onclick=()=>replaceSelection(b.dataset.rescuePick,Number(b.dataset.rescueIndex)));
 root.querySelectorAll('[data-transform-lunch]').forEach(b=>b.onclick=()=>enableLunchTransform(Number(b.dataset.transformLunch)));
 root.querySelectorAll('[data-account]').forEach(b=>b.onclick=showAccount);
 root.querySelectorAll('[data-trial-info]').forEach(b=>b.onclick=showTrialInfo);
}


communityUI.bootstrap();
